('category_hukum_posts', 'O:42:\"Illuminate\\Pagination\\LengthAwarePaginator\":12:{s:8:\"\0*\0items\";O:39:\"Illuminate\\Database\\Eloquent\\Collection\":2:{s:8:\"\0*\0items\";a:0:{}s:28:\"\0*\0escapeWhenCastingToString\";b:0;}s:10:\"\0*\0perPage\";i:12;s:14:\"\0*\0currentPage\";i:1;s:7:\"\0*\0path\";s:48:\"https://kabaruntukrakyat.com/blog/category/hukum\";s:8:\"\0*\0query\";a:0:{}s:11:\"\0*\0fragment\";N;s:11:\"\0*\0pageName\";s:4:\"page\";s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:10:\"onEachSide\";i:3;s:10:\"\0*\0options\";a:2:{s:4:\"path\";s:48:\"https://kabaruntukrakyat.com/blog/category/hukum\";s:8:\"pageName\";s:4:\"page\";}s:8:\"\0*\0total\";i:0;s:11:\"\0*\0lastPage\";i:1;}', 1788416946),
('category_lingkungan_posts', 'O:42:\"Illuminate\\Pagination\\LengthAwarePaginator\":12:{s:8:\"\0*\0items\";O:39:\"Illuminate\\Database\\Eloquent\\Collection\":2:{s:8:\"\0*\0items\";a:1:{i:0;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:1;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KC0RXXDEQY044E9PBM6CGKGH.jpeg\";s:5:\"title\";s:66:\"Sosialisasi Empat Pilar, Anna Muawanah Bahas Kesenjangan Desa-Kota\";s:4:\"slug\";s:65:\"sosialisasi-empat-pilar-anna-muawanah-bahas-kesenjangan-desa-kota\";s:4:\"body\";s:3424:\"<p>Bojonegoro 8 Desember 2025– Anggota DPR RI Anna Muawanah, kembali menggelar kegiatan Sosialisasi Empat Pilar MPR RI di wilayah Daerah Pemilihan Jawa Timur IX yang meliputi Bojonegoro dan Tuban. Kegiatan ini menjadi ruang dialog terbuka antara wakil rakyat dan masyarakat dalam menyikapi berbagai persoalan kebangsaan yang kian kompleks, mulai dari kesenjangan ekonomi, sulitnya akses lapangan kerja bagi generasi muda, hingga lemahnya literasi digital masyarakat.<br>Dalam pemaparannya, Anna Muawanah menegaskan bahwa nilai-nilai Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika harus menjadi landasan utama dalam mencari solusi atas berbagai persoalan sosial yang dihadapi masyarakat saat ini.<br>“Kesenjangan ekonomi yang semakin terasa, khususnya antara desa dan kota, tidak boleh dibiarkan. Negara harus hadir memastikan keadilan sosial benar-benar dirasakan oleh seluruh rakyat, sebagaimana amanat sila kelima Pancasila dan Pasal 33 UUD 1945,” tegas ibu Anna mu\'awanah di hadapan peserta sosialisasi.<br>Menurutnya, tantangan terbesar saat ini juga dirasakan oleh generasi muda yang menghadapi terbatasnya lapangan kerja layak, di tengah pesatnya perkembangan teknologi dan perubahan struktur ekonomi.<br>“Anak muda kita banyak yang cerdas dan kreatif, tetapi belum semuanya memiliki akses terhadap pekerjaan yang sesuai dengan kompetensi mereka. Negara harus mendorong pendidikan vokasi, kewirausahaan, dan membuka ruang industri berbasis potensi lokal agar anak muda tidak hanya menjadi penonton di daerahnya sendiri,” ujar ibu Anna.<br>Selain persoalan ekonomi dan ketenagakerjaan, ibu Anna mu\'awanah juga menyoroti lemahnya literasi digital masyarakat yang berdampak pada maraknya penyebaran hoaks, penipuan daring, hingga penyalahgunaan media sosial.<br>“Literasi digital bukan lagi kebutuhan tambahan, tetapi kebutuhan utama. Masyarakat harus dibekali kemampuan memilah informasi yang benar, agar tidak mudah terprovokasi dan tetap menjaga persatuan bangsa,” tambahnya.<br>Kegiatan sosialisasi ini juga diwarnai dengan penyampaian aspirasi dari masyarakat. Salah satu perwakilan masyarakat, Sutrisno, warga Bojonegoro, mengungkapkan bahwa persoalan ekonomi dan pekerjaan masih menjadi keluhan utama di tingkat desa.<br>“Kami merasakan langsung susahnya mencari pekerjaan, khususnya bagi anak-anak muda. Banyak yang akhirnya merantau karena di daerah sendiri sulit mendapatkan peluang kerja. Kami berharap ada program nyata yang langsung menyentuh desa,” ungkapnya.<br>Sementara itu, perwakilan peserta dari mahasiswa, Siti Rofiah, menilai bahwa literasi digital di masyarakat masih perlu mendapat perhatian serius.<br>“Sekarang hampir semua orang memegang ponsel, tapi tidak semuanya paham cara menggunakan media sosial dengan bijak. Banyak yang mudah percaya berita bohong, bahkan ikut menyebarkannya. Kami berharap ada pendampingan dan edukasi digital secara berkelanjutan,” ujarnya.<br>Menutup kegiatan tersebut, Anna Muawanah menegaskan komitmennya untuk terus memperjuangkan aspirasi masyarakat Bojonegoro dan Tuban, khususnya terkait pemerataan ekonomi, perluasan lapangan kerja bagi generasi muda, serta penguatan literasi digital.<br>“Empat Pilar bukan sekadar slogan, tetapi pedoman hidup berbangsa. Jika seluruh elemen masyarakat memegang teguh nilai-nilai itu, saya yakin persoalan sebesar apa pun bisa kita hadapi bersama dengan semangat gotong royong,” pungkasnya.</p>\";s:12:\"published_at\";s:19:\"2025-12-09 00:23:00\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2025-12-09 05:21:44\";s:10:\"updated_at\";s:19:\"2025-12-10 14:29:12\";}s:11:\"\0*\0original\";a:13:{s:2:\"id\";i:1;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KC0RXXDEQY044E9PBM6CGKGH.jpeg\";s:5:\"title\";s:66:\"Sosialisasi Empat Pilar, Anna Muawanah Bahas Kesenjangan Desa-Kota\";s:4:\"slug\";s:65:\"sosialisasi-empat-pilar-anna-muawanah-bahas-kesenjangan-desa-kota\";s:4:\"body\";s:3424:\"<p>Bojonegoro 8 Desember 2025– Anggota DPR RI Anna Muawanah, kembali menggelar kegiatan Sosialisasi Empat Pilar MPR RI di wilayah Daerah Pemilihan Jawa Timur IX yang meliputi Bojonegoro dan Tuban. Kegiatan ini menjadi ruang dialog terbuka antara wakil rakyat dan masyarakat dalam menyikapi berbagai persoalan kebangsaan yang kian kompleks, mulai dari kesenjangan ekonomi, sulitnya akses lapangan kerja bagi generasi muda, hingga lemahnya literasi digital masyarakat.<br>Dalam pemaparannya, Anna Muawanah menegaskan bahwa nilai-nilai Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika harus menjadi landasan utama dalam mencari solusi atas berbagai persoalan sosial yang dihadapi masyarakat saat ini.<br>“Kesenjangan ekonomi yang semakin terasa, khususnya antara desa dan kota, tidak boleh dibiarkan. Negara harus hadir memastikan keadilan sosial benar-benar dirasakan oleh seluruh rakyat, sebagaimana amanat sila kelima Pancasila dan Pasal 33 UUD 1945,” tegas ibu Anna mu\'awanah di hadapan peserta sosialisasi.<br>Menurutnya, tantangan terbesar saat ini juga dirasakan oleh generasi muda yang menghadapi terbatasnya lapangan kerja layak, di tengah pesatnya perkembangan teknologi dan perubahan struktur ekonomi.<br>“Anak muda kita banyak yang cerdas dan kreatif, tetapi belum semuanya memiliki akses terhadap pekerjaan yang sesuai dengan kompetensi mereka. Negara harus mendorong pendidikan vokasi, kewirausahaan, dan membuka ruang industri berbasis potensi lokal agar anak muda tidak hanya menjadi penonton di daerahnya sendiri,” ujar ibu Anna.<br>Selain persoalan ekonomi dan ketenagakerjaan, ibu Anna mu\'awanah juga menyoroti lemahnya literasi digital masyarakat yang berdampak pada maraknya penyebaran hoaks, penipuan daring, hingga penyalahgunaan media sosial.<br>“Literasi digital bukan lagi kebutuhan tambahan, tetapi kebutuhan utama. Masyarakat harus dibekali kemampuan memilah informasi yang benar, agar tidak mudah terprovokasi dan tetap menjaga persatuan bangsa,” tambahnya.<br>Kegiatan sosialisasi ini juga diwarnai dengan penyampaian aspirasi dari masyarakat. Salah satu perwakilan masyarakat, Sutrisno, warga Bojonegoro, mengungkapkan bahwa persoalan ekonomi dan pekerjaan masih menjadi keluhan utama di tingkat desa.<br>“Kami merasakan langsung susahnya mencari pekerjaan, khususnya bagi anak-anak muda. Banyak yang akhirnya merantau karena di daerah sendiri sulit mendapatkan peluang kerja. Kami berharap ada program nyata yang langsung menyentuh desa,” ungkapnya.<br>Sementara itu, perwakilan peserta dari mahasiswa, Siti Rofiah, menilai bahwa literasi digital di masyarakat masih perlu mendapat perhatian serius.<br>“Sekarang hampir semua orang memegang ponsel, tapi tidak semuanya paham cara menggunakan media sosial dengan bijak. Banyak yang mudah percaya berita bohong, bahkan ikut menyebarkannya. Kami berharap ada pendampingan dan edukasi digital secara berkelanjutan,” ujarnya.<br>Menutup kegiatan tersebut, Anna Muawanah menegaskan komitmennya untuk terus memperjuangkan aspirasi masyarakat Bojonegoro dan Tuban, khususnya terkait pemerataan ekonomi, perluasan lapangan kerja bagi generasi muda, serta penguatan literasi digital.<br>“Empat Pilar bukan sekadar slogan, tetapi pedoman hidup berbangsa. Jika seluruh elemen masyarakat memegang teguh nilai-nilai itu, saya yakin persoalan sebesar apa pun bisa kita hadapi bersama dengan semangat gotong royong,” pungkasnya.</p>\";s:12:\"published_at\";s:19:\"2025-12-09 00:23:00\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2025-12-09 05:21:44\";s:10:\"updated_at\";s:19:\"2025-12-10 14:29:12\";s:17:\"pivot_category_id\";i:6;s:13:\"pivot_post_id\";i:1;}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:1:{s:5:\"pivot\";O:44:\"Illuminate\\Database\\Eloquent\\Relations\\Pivot\":37:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:13:\"category_post\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:0;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:2:{s:11:\"category_id\";i:6;s:7:\"post_id\";i:1;}s:11:\"\0*\0original\";a:2:{s:11:\"category_id\";i:6;s:7:\"post_id\";i:1;}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:0:{}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:0;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\