INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('category_teknologi_posts', 'O:42:\"Illuminate\\Pagination\\LengthAwarePaginator\":12:{s:8:\"\0*\0items\";O:39:\"Illuminate\\Database\\Eloquent\\Collection\":2:{s:8:\"\0*\0items\";a:1:{i:0;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:7;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KJ83QT2ADFKDM3DHANA4H0CM.jpeg\";s:5:\"title\";s:35:\"Malam Keakraban (Makrab) SISKOMFEST\";s:4:\"slug\";s:33:\"malam-keakraban-makrab-siskomfest\";s:4:\"body\";s:1349:\"<p><strong>Kegiatan Malam Keakraban (Makrab) SISKOMFEST</strong> yang dilaksanakan pada tanggal 14–15 Januari 2026 di Pantai Semilir diikuti oleh 66 peserta yang merupakan mahasiswa Program Studi Sistem Komputer angkatan 2023, 2024, dan 2025. Kegiatan ini turut dihadiri oleh Kepala Program Studi Sistem Komputer, Dwi Issadari Hastuti, S.Pd., S.Kom., M.Kom., serta Ketua Himpunan Mahasiswa Sistem Komputer yang mendampingi jalannya kegiatan.<br><br>Dalam sambutannya, Abdul Ghofur menyampaikan harapannya agar kegiatan Makrab ini dapat menjadi dasar terbentuknya solidaritas yang kuat antar mahasiswa Sistem Komputer lintas angkatan. Selain itu, kegiatan ini juga diharapkan menjadi wadah bagi mahasiswa untuk berkembang, serta sebagai sarana perkenalan organisasi Program Studi kepada mahasiswa baru agar lebih mengenal lingkungan akademik dan organisasi kemahasiswaan.<br><br>Sementara itu, Ibu Dwi Issadari Hastuti juga menyampaikan harapan besar agar dengan terselenggaranya kegiatan Makrab SISKOMFEST ini, tali silaturahmi antar mahasiswa, dosen, dan seluruh civitas akademika Program Studi Sistem Komputer dapat terus terjaga, tidak terputus, serta semakin kuat dan kompak. Beliau berharap kegiatan ini dapat terus dikembangkan di masa mendatang agar semakin baik dan memberikan dampak positif bagi mahasiswa Sistem Komputer ke depannya.</p>\";s:12:\"published_at\";s:19:\"2026-02-23 22:08:55\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-24 15:19:31\";s:10:\"updated_at\";s:19:\"2026-02-24 15:19:31\";}s:11:\"\0*\0original\";a:13:{s:2:\"id\";i:7;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KJ83QT2ADFKDM3DHANA4H0CM.jpeg\";s:5:\"title\";s:35:\"Malam Keakraban (Makrab) SISKOMFEST\";s:4:\"slug\";s:33:\"malam-keakraban-makrab-siskomfest\";s:4:\"body\";s:1349:\"<p><strong>Kegiatan Malam Keakraban (Makrab) SISKOMFEST</strong> yang dilaksanakan pada tanggal 14–15 Januari 2026 di Pantai Semilir diikuti oleh 66 peserta yang merupakan mahasiswa Program Studi Sistem Komputer angkatan 2023, 2024, dan 2025. Kegiatan ini turut dihadiri oleh Kepala Program Studi Sistem Komputer, Dwi Issadari Hastuti, S.Pd., S.Kom., M.Kom., serta Ketua Himpunan Mahasiswa Sistem Komputer yang mendampingi jalannya kegiatan.<br><br>Dalam sambutannya, Abdul Ghofur menyampaikan harapannya agar kegiatan Makrab ini dapat menjadi dasar terbentuknya solidaritas yang kuat antar mahasiswa Sistem Komputer lintas angkatan. Selain itu, kegiatan ini juga diharapkan menjadi wadah bagi mahasiswa untuk berkembang, serta sebagai sarana perkenalan organisasi Program Studi kepada mahasiswa baru agar lebih mengenal lingkungan akademik dan organisasi kemahasiswaan.<br><br>Sementara itu, Ibu Dwi Issadari Hastuti juga menyampaikan harapan besar agar dengan terselenggaranya kegiatan Makrab SISKOMFEST ini, tali silaturahmi antar mahasiswa, dosen, dan seluruh civitas akademika Program Studi Sistem Komputer dapat terus terjaga, tidak terputus, serta semakin kuat dan kompak. Beliau berharap kegiatan ini dapat terus dikembangkan di masa mendatang agar semakin baik dan memberikan dampak positif bagi mahasiswa Sistem Komputer ke depannya.</p>\";s:12:\"published_at\";s:19:\"2026-02-23 22:08:55\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-24 15:19:31\";s:10:\"updated_at\";s:19:\"2026-02-24 15:19:31\";s:17:\"pivot_category_id\";i:7;s:13:\"pivot_post_id\";i:7;}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:1:{s:5:\"pivot\";O:44:\"Illuminate\\Database\\Eloquent\\Relations\\Pivot\":37:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:13:\"category_post\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:0;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:2:{s:11:\"category_id\";i:7;s:7:\"post_id\";i:7;}s:11:\"\0*\0original\";a:2:{s:11:\"category_id\";i:7;s:7:\"post_id\";i:7;}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:0:{}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:0;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:0:{}s:10:\"\0*\0guarded\";a:0:{}s:11:\"pivotParent\";O:19:\"App\\Models\\Category\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:10:\"categories\