0;}}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:2;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:5;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KH0F54N4JZ8KT3MKBSJ9T9WS.jpeg\";s:5:\"title\";s:68:\"Anna Mu’awanah Ajak Para Pemuda Memperkuat Nilai-Nilai Kebangsaan.\";s:4:\"slug\";s:64:\"anna-muawanah-ajak-para-pemuda-memperkuat-nilai-nilai-kebangsaan\";s:4:\"body\";s:1490:\"<p>Tuban, 07 Februari 2026 — Anggota DPR RI sekaligus MPR RI, Anna Mu’awanah, menggelar kegiatan Sosialisasi Empat Pilar Kebangsaan. Kegiatan ini dihadiri oleh Para Tokoh Pemuda.</p><p>&nbsp;</p><p>Dalam pemaparannya, Anna Mu’awanah menyoroti berbagai permasalahan kebangsaan yang semakin kompleks di tahun 2026, yakni perkembangan politik global yang semankin tidak menentu.</p><p>Maka dari Itu Anna Mu\'awanah menyampaikan agar masyarakat menjaga kesatuan dan persatuan serta pentingnya penguatan nilai-nilai Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika sebagai pedoman hidup berbangsa dan bernegara.&nbsp;</p><p>&nbsp;</p><p>Ibu Anna menambahkan, bahwa Ibu Anna sangat mengharapkan agar apa yang telah di sosialisasikan hari ini bisa diterapkan dalam kehidupan sehari-hari di masyarakat luas sehingga kita bisa melindungi generasi muda dari gangguan apapun yang dapat memecah belah bangsa.</p><p>&nbsp;</p><p>Kegiatan sosialisasi ini berlangsung secara dialogis dan partisipatif. Para peserta yang terdiri dari tokoh pemuda terlihat antusias mengikuti pemaparan materi serta berdiskusi mengenai peran masyarakat dalam mengamalkan nilai-nilai Pancasila dan semangat kebangsaan.</p><p>&nbsp;</p><p>Melalui kegiatan Sosialisasi Empat Pilar Kebangsaan ini Ibu Anna berharap pemahaman masyarakat terutama para pemuda terhadap nilai-nilai kebangsaan semakin meningkat dan mampu memperkokoh persatuan bangsa dalam mewujudkan Indonesia yang berdaulat, mandiri dan berkepribadian.</p>\";s:12:\"published_at\";s:19:\"2026-02-07 12:48:41\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-09 05:49:25\";s:10:\"updated_at\";s:19:\"2026-02-24 15:03:21\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:5;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KH0F54N4JZ8KT3MKBSJ9T9WS.jpeg\";s:5:\"title\";s:68:\"Anna Mu’awanah Ajak Para Pemuda Memperkuat Nilai-Nilai Kebangsaan.\";s:4:\"slug\";s:64:\"anna-muawanah-ajak-para-pemuda-memperkuat-nilai-nilai-kebangsaan\";s:4:\"body\";s:1490:\"<p>Tuban, 07 Februari 2026 — Anggota DPR RI sekaligus MPR RI, Anna Mu’awanah, menggelar kegiatan Sosialisasi Empat Pilar Kebangsaan. Kegiatan ini dihadiri oleh Para Tokoh Pemuda.</p><p>&nbsp;</p><p>Dalam pemaparannya, Anna Mu’awanah menyoroti berbagai permasalahan kebangsaan yang semakin kompleks di tahun 2026, yakni perkembangan politik global yang semankin tidak menentu.</p><p>Maka dari Itu Anna Mu\'awanah menyampaikan agar masyarakat menjaga kesatuan dan persatuan serta pentingnya penguatan nilai-nilai Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika sebagai pedoman hidup berbangsa dan bernegara.&nbsp;</p><p>&nbsp;</p><p>Ibu Anna menambahkan, bahwa Ibu Anna sangat mengharapkan agar apa yang telah di sosialisasikan hari ini bisa diterapkan dalam kehidupan sehari-hari di masyarakat luas sehingga kita bisa melindungi generasi muda dari gangguan apapun yang dapat memecah belah bangsa.</p><p>&nbsp;</p><p>Kegiatan sosialisasi ini berlangsung secara dialogis dan partisipatif. Para peserta yang terdiri dari tokoh pemuda terlihat antusias mengikuti pemaparan materi serta berdiskusi mengenai peran masyarakat dalam mengamalkan nilai-nilai Pancasila dan semangat kebangsaan.</p><p>&nbsp;</p><p>Melalui kegiatan Sosialisasi Empat Pilar Kebangsaan ini Ibu Anna berharap pemahaman masyarakat terutama para pemuda terhadap nilai-nilai kebangsaan semakin meningkat dan mampu memperkokoh persatuan bangsa dalam mewujudkan Indonesia yang berdaulat, mandiri dan berkepribadian.</p>\";s:12:\"published_at\";s:19:\"2026-02-07 12:48:41\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-09 05:49:25\";s:10:\"updated_at\";s:19:\"2026-02-24 15:03:21\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:1:{s:10:\"categories\";O:39:\"Illuminate\\Database\\Eloquent\\Collection\":2:{s:8:\"\0*\0items\";a:1:{i:0;O:19:\"App\\Models\\Category\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:10:\"categories\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:7:{s:2:\"id\";i:3;s:5:\"title\";s:21:\"Sosial kemasyarakatan\";s:4:\"slug\";s:21:\"sosial-kemasyarakatan\";s:10:\"text_color\";N;s:8:\"bg_color\";N;s:10:\"created