;s:13:\"\0*\0relatedKey\";s:11:\"category_id\";}}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:4:{i:0;s:5:\"title\";i:1;s:4:\"slug\";i:2;s:10:\"text_color\";i:3;s:8:\"bg_color\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}}}s:28:\"\0*\0escapeWhenCastingToString\";b:0;}}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}}s:28:\"\0*\0escapeWhenCastingToString\";b:0;}', 1788497697);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('latestPosts', 'O:39:\"Illuminate\\Database\\Eloquent\\Collection\":2:{s:8:\"\0*\0items\";a:9:{i:0;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:11;s:7:\"user_id\";i:3;s:5:\"image\";s:47:\"posts/thumbnails/01KVYNZ1A7G62H2XTTPTRX8FHP.jpg\";s:5:\"title\";s:102:\"Sosialisasi Empat Pilar MPR RI Bersama Dr. Hj. Anna Mu’awanah, S.E., M.H. di Politeknik MAPENA Tuban\";s:4:\"slug\";s:91:\"sosialisasi-empat-pilar-mpr-ri-bersama-dr-hj-anna-muawanah-se-mh-di-politeknik-mapena-tuban\";s:4:\"body\";s:3141:\"<p><strong>Tuban</strong> – Anggota MPR RI, Anna Mu\'awanah, menyelenggarakan kegiatan <strong>Sosialisasi Empat Pilar MPR RI</strong> yang bertempat di Aula Politeknik MAPENA Tuban. Kegiatan tersebut diikuti oleh perwakilan tokoh perempuan dari berbagai kecamatan di Kabupaten Tuban sebagai bagian dari upaya memperkuat pemahaman masyarakat terhadap nilai-nilai kebangsaan dan kehidupan bernegara.</p><p>Dalam sambutannya, Dr. Hj. Anna Mu’awanah, S.E., M.H. menyampaikan bahwa Empat Pilar MPR RI yang terdiri atas <strong>Pancasila sebagai Dasar dan Ideologi Negara, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika</strong> merupakan fondasi utama dalam menjaga persatuan dan kesatuan bangsa di tengah berbagai tantangan kehidupan bermasyarakat, berbangsa, dan bernegara.</p><p>Menurutnya, perempuan memiliki peran strategis dalam menanamkan nilai-nilai kebangsaan, toleransi, dan gotong royong, terutama dalam lingkungan keluarga dan masyarakat. Oleh karena itu, peningkatan pemahaman terhadap Empat Pilar MPR RI menjadi sangat penting agar perempuan dapat menjadi agen perubahan yang mampu memperkuat karakter bangsa dan menjaga harmonisasi sosial di tengah keberagaman.</p><p>“Perempuan merupakan madrasah pertama bagi generasi bangsa. Dari keluarga lahir nilai-nilai kebangsaan, toleransi, dan semangat persatuan yang harus terus dijaga. Karena itu, pemahaman terhadap Empat Pilar MPR RI menjadi bekal penting bagi para tokoh perempuan untuk berkontribusi dalam pembangunan bangsa,” ujar Anna Mu’awanah.</p><p>Dalam pemaparannya, Anna Mu’awanah menjelaskan bahwa Pancasila bukan hanya dasar negara, tetapi juga pedoman hidup yang harus diimplementasikan dalam kehidupan sehari-hari. Sementara itu, UUD NRI Tahun 1945 menjadi landasan konstitusional dalam penyelenggaraan negara yang menjamin hak dan kewajiban seluruh warga negara. Adapun NKRI merupakan bentuk negara yang harus terus dijaga keutuhannya, sedangkan Bhinneka Tunggal Ika menjadi perekat keberagaman suku, agama, budaya, dan golongan yang dimiliki Indonesia.</p><p>Kegiatan berlangsung secara interaktif dengan sesi dialog dan tanya jawab. Para peserta menyampaikan berbagai pandangan terkait peran perempuan dalam menjaga persatuan bangsa, meningkatkan partisipasi masyarakat dalam pembangunan, serta menghadapi tantangan sosial di era digital yang semakin kompleks.</p><p>Para peserta mengapresiasi penyelenggaraan kegiatan tersebut karena memberikan pemahaman yang lebih mendalam mengenai pentingnya penguatan wawasan kebangsaan. Mereka berharap kegiatan serupa dapat terus dilaksanakan secara berkelanjutan sehingga nilai-nilai Empat Pilar MPR RI semakin membumi dan menjadi pedoman dalam kehidupan masyarakat.</p><p>Melalui kegiatan Sosialisasi Empat Pilar MPR RI ini, diharapkan para tokoh perempuan Kabupaten Tuban dapat menjadi mitra strategis dalam memperkuat semangat nasionalisme, menjaga persatuan dan kesatuan bangsa, serta menanamkan nilai-nilai kebangsaan kepada generasi muda demi terwujudnya Indonesia yang maju, berdaulat, dan berkepribadian dalam kebudayaan.</p>\";s:12:\"published_at\";s:19:\"2026-06-17 20:00:17\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-06-25 06:02:36\";s:10:\"updated_at\";s:19:\"2026-06-25 06:02:36\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:11;s:7:\"user_id\";i:3;s:5:\"image\";s:47:\"posts/thumbnails/01KVYNZ1A7G62H2XTTPTRX8FHP.jpg\";s:5:\"title\";s:102:\"Sosialisasi Empat Pilar MPR RI Bersama Dr. Hj. Anna Mu’awanah, S.E., M.H. di Politeknik MAPENA Tuban\";s:4:\"slug\";s:91:\"sosialisasi-empat-pilar-mpr-ri-bersama-dr-hj-anna-muawanah-se-mh-di-politeknik-mapena-tuban\";s:4:\"body\";s:3141:\"<p><strong>Tuban</strong> – Anggota MPR RI, Anna Mu\'awanah, menyelenggarakan kegiatan <strong>Sosialisasi Empat Pilar MPR RI</strong> yang bertempat di Aula Politeknik MAPENA Tuban. Kegiatan tersebut diikuti oleh perwakilan tokoh perempuan dari berbagai kecamatan di Kabupaten Tuban sebagai bagian dari upaya memperkuat pemahaman masyarakat terhadap nilai-nilai kebangsaan dan kehidupan bernegara.</p><p>Dalam sambutannya, Dr. Hj. Anna Mu’awanah, S.E., M.H. menyampaikan bahwa Empat Pilar MPR RI yang terdiri atas <strong>Pancasila sebagai Dasar dan Ideologi Negara, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika</strong> merupakan fondasi utama dalam menjaga persatuan dan kesatuan bangsa di tengah berbagai tantangan kehidupan bermasyarakat, berbangsa, dan bernegara.</p><p>Menurutnya, perempuan memiliki peran strategis dalam menanamkan nilai-nilai kebangsaan, toleransi, dan gotong royong, terutama dalam lingkungan keluarga dan masyarakat. Oleh karena itu, peningkatan pemahaman terhadap Empat Pilar MPR RI menjadi sangat penting agar perempuan dapat menjadi agen perubahan yang mampu memperkuat karakter bangsa dan menjaga harmonisasi sosial di tengah keberagaman.</p><p>“Perempuan merupakan madrasah pertama bagi generasi bangsa. Dari keluarga lahir nilai-nilai kebangsaan, toleransi, dan semangat persatuan yang harus terus dijaga. Karena itu, pemahaman terhadap Empat Pilar MPR RI menjadi bekal penting bagi para tokoh perempuan untuk berkontribusi dalam pembangunan bangsa,” ujar Anna Mu’awanah.</p><p>Dalam pemaparannya, Anna Mu’awanah menjelaskan bahwa Pancasila bukan hanya dasar negara, tetapi juga pedoman hidup yang harus diimplementasikan dalam kehidupan sehari-hari. Sementara itu, UUD NRI Tahun 1945 menjadi landasan konstitusional dalam penyelenggaraan negara yang menjamin hak dan kewajiban seluruh warga negara. Adapun NKRI merupakan bentuk negara yang harus terus dijaga keutuhannya, sedangkan Bhinneka Tunggal Ika menjadi perekat keberagaman suku, agama, budaya, dan golongan yang dimiliki Indonesia.</p><p>Kegiatan berlangsung secara interaktif dengan sesi dialog dan tanya jawab. Para peserta menyampaikan berbagai pandangan terkait peran perempuan dalam menjaga persatuan bangsa, meningkatkan partisipasi masyarakat dalam pembangunan, serta menghadapi tantangan sosial di era digital yang semakin kompleks.</p><p>Para peserta mengapresiasi penyelenggaraan kegiatan tersebut karena memberikan pemahaman yang lebih mendalam mengenai pentingnya penguatan wawasan kebangsaan. Mereka berharap kegiatan serupa dapat terus dilaksanakan secara berkelanjutan sehingga nilai-nilai Empat Pilar MPR RI semakin membumi dan menjadi pedoman dalam kehidupan masyarakat.</p><p>Melalui kegiatan Sosialisasi Empat Pilar MPR RI ini, diharapkan para tokoh perempuan Kabupaten Tuban dapat menjadi mitra strategis dalam memperkuat semangat nasionalisme, menjaga persatuan dan kesatuan bangsa, serta menanamkan nilai-nilai kebangsaan kepada generasi muda demi terwujudnya Indonesia yang maju, berdaulat, dan berkepribadian dalam kebudayaan.</p>\";s:12:\"published_at\";s:19:\"2026-06-17 20:00:17\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-06-25 06:02:36\";s:10:\"updated_at\";s:19:\"2026-06-25 06:02:36\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0prev