"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:1;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:10;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KNGAVKWZQDZKMKSJT5TVF6CF.jpeg\";s:5:\"title\";s:120:\"Peran Perempuan dalam Menguatkan Nilai-Nilai Kebangsaan, DR. Anna Mu’awanah Sosialisasikan Empat Pilar MPR RI di Tuban\";s:4:\"slug\";s:115:\"peran-perempuan-dalam-menguatkan-nilai-nilai-kebangsaan-dr-anna-muawanah-sosialisasikan-empat-pilar-mpr-ri-di-tuban\";s:4:\"body\";s:2219:\"<p>Tuban – Dalam upaya memperkuat pemahaman nilai-nilai kebangsaan di tengah masyarakat, Dr. Anna Mu’awanah selaku Anggota MPR RI menggelar kegiatan Sosialisasi Empat Pilar MPR RI dengan mengusung tema <em>“Peran Perempuan dalam Menguatkan Nilai-Nilai Kebangsaan”</em>. Kegiatan ini dilaksanakan pada tanggal 4 April 2026 di Kabupaten Tuban, dengan melibatkan peserta dari kalangan perempuan, tokoh masyarakat, serta perwakilan organisasi perempuan setempat.</p><p>Dalam paparannya, Dr. Anna Mu’awanah menegaskan bahwa perempuan memiliki posisi strategis dalam menanamkan nilai-nilai kebangsaan, khususnya dalam lingkup keluarga sebagai unit terkecil dalam kehidupan berbangsa dan bernegara. Menurutnya, nilai-nilai yang terkandung dalam Empat Pilar MPR RI, yakni Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia, dan Bhinneka Tunggal Ika, harus terus diinternalisasikan dalam kehidupan sehari-hari.</p><p>“Perempuan adalah madrasah pertama bagi anak-anaknya. Dari tangan perempuanlah nilai-nilai Pancasila, semangat persatuan, serta sikap toleransi dan gotong royong dapat ditanamkan sejak dini,” ujar beliau.</p><p>Lebih lanjut, ia juga mengajak para peserta untuk menjadi agen perubahan di lingkungan masing-masing, terutama dalam menghadapi tantangan zaman seperti derasnya arus informasi digital, hoaks, serta potensi disintegrasi bangsa. Perempuan diharapkan mampu menjadi garda terdepan dalam menjaga harmoni sosial serta memperkuat persatuan di tengah keberagaman.</p><p>Kegiatan ini berlangsung dengan interaktif, di mana para peserta turut menyampaikan aspirasi, pandangan, serta pengalaman mereka terkait peran perempuan dalam menjaga nilai-nilai kebangsaan di lingkungan keluarga dan masyarakat. Aspirasi yang muncul di antaranya pentingnya peningkatan literasi digital bagi perempuan, penguatan pendidikan karakter, serta dukungan terhadap peran perempuan dalam pembangunan daerah.</p><p>Melalui kegiatan sosialisasi ini, diharapkan nilai-nilai Empat Pilar MPR RI semakin mengakar dalam kehidupan masyarakat, khususnya di kalangan perempuan, sehingga dapat menjadi fondasi kuat dalam menjaga keutuhan dan kedaulatan bangsa Indonesia.</p>\";s:12:\"published_at\";s:19:\"2026-04-04 09:42:38\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-04-06 02:42:59\";s:10:\"updated_at\";s:19:\"2026-04-06 02:44:56\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:10;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KNGAVKWZQDZKMKSJT5TVF6CF.jpeg\";s:5:\"title\";s:120:\"Peran Perempuan dalam Menguatkan Nilai-Nilai Kebangsaan, DR. Anna Mu’awanah Sosialisasikan Empat Pilar MPR RI di Tuban\";s:4:\"slug\";s:115:\"peran-perempuan-dalam-menguatkan-nilai-nilai-kebangsaan-dr-anna-muawanah-sosialisasikan-empat-pilar-mpr-ri-di-tuban\";s:4:\"body\";s:2219:\"<p>Tuban – Dalam upaya memperkuat pemahaman nilai-nilai kebangsaan di tengah masyarakat, Dr. Anna Mu’awanah selaku Anggota MPR RI menggelar kegiatan Sosialisasi Empat Pilar MPR RI dengan mengusung tema <em>“Peran Perempuan dalam Menguatkan Nilai-Nilai Kebangsaan”</em>. Kegiatan ini dilaksanakan pada tanggal 4 April 2026 di Kabupaten Tuban, dengan melibatkan peserta dari kalangan perempuan, tokoh masyarakat, serta perwakilan organisasi perempuan setempat.</p><p>Dalam paparannya, Dr. Anna Mu’awanah menegaskan bahwa perempuan memiliki posisi strategis dalam menanamkan nilai-nilai kebangsaan, khususnya dalam lingkup keluarga sebagai unit terkecil dalam kehidupan berbangsa dan bernegara. Menurutnya, nilai-nilai yang terkandung dalam Empat Pilar MPR RI, yakni Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia, dan Bhinneka Tunggal Ika, harus terus diinternalisasikan dalam kehidupan sehari-hari.</p><p>“Perempuan adalah madrasah pertama bagi anak-anaknya. Dari tangan perempuanlah nilai-nilai Pancasila, semangat persatuan, serta sikap toleransi dan gotong royong dapat ditanamkan sejak dini,” ujar beliau.</p><p>Lebih lanjut, ia juga mengajak para peserta untuk menjadi agen perubahan di lingkungan masing-masing, terutama dalam menghadapi tantangan zaman seperti derasnya arus informasi digital, hoaks, serta potensi disintegrasi bangsa. Perempuan diharapkan mampu menjadi garda terdepan dalam menjaga harmoni sosial serta memperkuat persatuan di tengah keberagaman.</p><p>Kegiatan ini berlangsung dengan interaktif, di mana para peserta turut menyampaikan aspirasi, pandangan, serta pengalaman mereka terkait peran perempuan dalam menjaga nilai-nilai kebangsaan di lingkungan keluarga dan masyarakat. Aspirasi yang muncul di antaranya pentingnya peningkatan literasi digital bagi perempuan, penguatan pendidikan karakter, serta dukungan terhadap peran perempuan dalam pembangunan daerah.</p><p>Melalui kegiatan sosialisasi ini, diharapkan nilai-nilai Empat Pilar MPR RI semakin mengakar dalam kehidupan masyarakat, khususnya di kalangan perempuan, sehingga dapat menjadi fondasi kuat dalam menjaga keutuhan dan kedaulatan bangsa Indonesia.</p>\";s:12:\"published_at\";s:19:\"2026-04-04 09:42:38\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-04-06 02:42:59\";s:10:\"updated_at\";s:19:\"2026-04-06 02:44:56\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:1:{s:10:\"categories\";O:39:\"Illuminate\\Database\\Eloquent\\Collection\":2:{s:8:\"\0*\0items\";a:1:{i:0;O:19:\"App\\Models\\Category\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:10:\"categories\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:7:{s:2:\"id\";i:3;s:5:\"title\";s:21:\"Sosial kemasyarakatan\";s:4:\"slug\";s:21:\"sosial-kemasyarakatan\";s:10:\"text_color\";N;s:8:\"bg_color\";N;s:10:\"created_at\";s:19:\"2025-12-08 16:11:30\";s:10:\"updated_at\";s:19:\"2025-12-08 16:11:30\";}s:11:\"\0*\0original\";a:9:{s:2:\"id\";i:3;s:5:\"title\";s:21:\"Sosial kemasyarakatan\";s:4:\"slug\";s:21:\"sosial-kemasyarakatan\";s:10:\"text_color\";N;s:8:\"bg_color\";N;s:10:\"created_at\";s:19:\"2025-12-08 16:11:30\";s:10:\"updated_at\";s:19:\"2025-12-08 16:11:30\";s:13:\"pivot_post_id\";i:10;s:17:\"pivot_category_id\";i:3;}s:10:\"\0*\