0*\0escapeWhenCastingToString\";b:0;}}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:2;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:9;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KN1BX6JHE8JAZYC1D5NN01RK.jpeg\";s:5:\"title\";s:133:\"Peran Strategis Aktivis Perempuan dalam Penguatan Nilai Kebangsaan: Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu’awanah di Tuban\";s:4:\"slug\";s:128:\"peran-strategis-aktivis-perempuan-dalam-penguatan-nilai-kebangsaan-sosialisasi-empat-pilar-mpr-ri-oleh-dr-anna-muawanah-di-tuban\";s:4:\"body\";s:1586:\"<p>Kegiatan Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu\'awanah dilaksanakan pada tanggal 16 Maret 2026, bertempat di Aula Politeknik Pertanian Mapena (Poltana Mapena). Kegiatan ini dihadiri oleh perwakilan para aktivis perempuan se-Kabupaten Tuban yang memiliki peran penting dalam mendorong perubahan sosial di tengah masyarakat.<br><br></p><p>Dalam pemaparannya, Dr. Anna Mu’awanah menegaskan pentingnya pemahaman dan pengamalan Empat Pilar MPR RI, yakni Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika, sebagai fondasi utama dalam kehidupan berbangsa dan bernegara.<br><br></p><p>Beliau juga menekankan peran strategis para aktivis perempuan sebagai agen perubahan dalam memperkuat nilai-nilai kebangsaan, menjaga persatuan, serta mendorong terciptanya masyarakat yang inklusif dan berkeadilan. Dalam era dinamika sosial yang terus berkembang, perempuan diharapkan mampu menjadi penggerak dalam menanamkan nilai toleransi, kebhinekaan, dan semangat gotong royong di lingkungan masing-masing.<br><br></p><p>Kegiatan berlangsung interaktif melalui sesi diskusi dan tanya jawab, di mana para peserta aktif menyampaikan pandangan serta pengalaman terkait implementasi nilai-nilai kebangsaan dalam kehidupan sehari-hari.<br><br></p><p>Melalui kegiatan ini, diharapkan para aktivis perempuan semakin memahami dan menginternalisasi nilai-nilai Empat Pilar MPR RI, serta dapat berkontribusi secara nyata dalam menjaga keutuhan bangsa dan memperkuat karakter kebangsaan di tengah masyarakat.</p>\";s:12:\"published_at\";s:19:\"2026-03-16 14:13:00\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-03-31 07:14:40\";s:10:\"updated_at\";s:19:\"2026-03-31 07:14:50\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:9;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KN1BX6JHE8JAZYC1D5NN01RK.jpeg\";s:5:\"title\";s:133:\"Peran Strategis Aktivis Perempuan dalam Penguatan Nilai Kebangsaan: Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu’awanah di Tuban\";s:4:\"slug\";s:128:\"peran-strategis-aktivis-perempuan-dalam-penguatan-nilai-kebangsaan-sosialisasi-empat-pilar-mpr-ri-oleh-dr-anna-muawanah-di-tuban\";s:4:\"body\";s:1586:\"<p>Kegiatan Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu\'awanah dilaksanakan pada tanggal 16 Maret 2026, bertempat di Aula Politeknik Pertanian Mapena (Poltana Mapena). Kegiatan ini dihadiri oleh perwakilan para aktivis perempuan se-Kabupaten Tuban yang memiliki peran penting dalam mendorong perubahan sosial di tengah masyarakat.<br><br></p><p>Dalam pemaparannya, Dr. Anna Mu’awanah menegaskan pentingnya pemahaman dan pengamalan Empat Pilar MPR RI, yakni Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika, sebagai fondasi utama dalam kehidupan berbangsa dan bernegara.<br><br></p><p>Beliau juga menekankan peran strategis para aktivis perempuan sebagai agen perubahan dalam memperkuat nilai-nilai kebangsaan, menjaga persatuan, serta mendorong terciptanya masyarakat yang inklusif dan berkeadilan. Dalam era dinamika sosial yang terus berkembang, perempuan diharapkan mampu menjadi penggerak dalam menanamkan nilai toleransi, kebhinekaan, dan semangat gotong royong di lingkungan masing-masing.<br><br></p><p>Kegiatan berlangsung interaktif melalui sesi diskusi dan tanya jawab, di mana para peserta aktif menyampaikan pandangan serta pengalaman terkait implementasi nilai-nilai kebangsaan dalam kehidupan sehari-hari.<br><br></p><p>Melalui kegiatan ini, diharapkan para aktivis perempuan semakin memahami dan menginternalisasi nilai-nilai Empat Pilar MPR RI, serta dapat berkontribusi secara nyata dalam menjaga keutuhan bangsa dan memperkuat karakter kebangsaan di tengah masyarakat.</p>\";s:12:\"published_at\";s:19:\"2026-03-16 14:13:00\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-03-31 07:14:40\";s:10:\"updated_at\";s:19:\"2026-03-31 07:14:50\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:1:{s:10:\"categories\";O:39:\"Illuminate\\Database\\Eloquent\\Collection\":2:{s:8:\"\0*\0items\";a:1:{i:0;O:19:\"App\\Models\\Category\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:10:\"categories\