;s:13:\"\0*\0relatedKey\";s:11:\"category_id\";}}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:4:{i:0;s:5:\"title\";i:1;s:4:\"slug\";i:2;s:10:\"text_color\";i:3;s:8:\"bg_color\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}}}s:28:\"\0*\0escapeWhenCastingToString\";b:0;}}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:5;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:6;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KH3CZC5PTA4KXG9H8JDCM672.jpeg\";s:5:\"title\";s:77:\"Ibu Anna Mu’awanah Gelar Sosialisasi Empat Pilar MPR RI untuk Generasi Muda\";s:4:\"slug\";s:74:\"ibu-anna-muawanah-gelar-sosialisasi-empat-pilar-mpr-ri-untuk-generasi-muda\";s:4:\"body\";s:1723:\"<p>Tuban - Dalam rangka memperkuat wawasan kebangsaan di kalangan generasi muda, <strong>Ibu Anna Mu’awanah</strong> menyelenggarakan kegiatan <strong>Sosialisasi Empat Pilar MPR RI</strong> pada <strong>Selasa, 10 Februari 2026</strong>. Kegiatan ini diikuti oleh <strong>pemuda dan pemudi</strong> dari berbagai latar belakang dengan antusiasme yang tinggi.</p><p>Sosialisasi ini bertujuan untuk menanamkan pemahaman yang mendalam mengenai <strong>Empat Pilar MPR RI</strong>, yaitu <strong>Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika</strong>. Keempat pilar tersebut menjadi landasan penting dalam kehidupan berbangsa dan bernegara, khususnya bagi generasi muda sebagai calon pemimpin masa depan.</p><p>Dalam sambutannya, Ibu Anna Mu’awanah menekankan pentingnya peran pemuda dalam menjaga persatuan dan keutuhan bangsa di tengah tantangan zaman yang semakin kompleks. Menurutnya, pemuda tidak hanya dituntut cerdas secara intelektual, tetapi juga harus memiliki karakter kebangsaan yang kuat serta menjunjung tinggi nilai-nilai toleransi dan persatuan.</p><p>Kegiatan berlangsung secara interaktif dengan penyampaian materi yang komunikatif, sehingga mudah dipahami oleh para peserta. Para pemuda diajak untuk mengimplementasikan nilai-nilai Empat Pilar MPR RI dalam kehidupan sehari-hari, baik di lingkungan pendidikan, sosial, maupun dalam bermedia digital.</p><p>Melalui kegiatan Sosialisasi Empat Pilar MPR RI ini, diharapkan generasi muda semakin memiliki kesadaran berbangsa dan bernegara, serta mampu menjadi agen perubahan yang positif dalam menjaga persatuan dan kesatuan Negara Kesatuan Republik Indonesia.</p>\";s:12:\"published_at\";s:19:\"2026-02-10 16:08:35\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-10 09:09:02\";s:10:\"updated_at\";s:19:\"2026-02-10 09:10:25\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:6;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KH3CZC5PTA4KXG9H8JDCM672.jpeg\";s:5:\"title\";s:77:\"Ibu Anna Mu’awanah Gelar Sosialisasi Empat Pilar MPR RI untuk Generasi Muda\";s:4:\"slug\";s:74:\"ibu-anna-muawanah-gelar-sosialisasi-empat-pilar-mpr-ri-untuk-generasi-muda\";s:4:\"body\";s:1723:\"<p>Tuban - Dalam rangka memperkuat wawasan kebangsaan di kalangan generasi muda, <strong>Ibu Anna Mu’awanah</strong> menyelenggarakan kegiatan <strong>Sosialisasi Empat Pilar MPR RI</strong> pada <strong>Selasa, 10 Februari 2026</strong>. Kegiatan ini diikuti oleh <strong>pemuda dan pemudi</strong> dari berbagai latar belakang dengan antusiasme yang tinggi.</p><p>Sosialisasi ini bertujuan untuk menanamkan pemahaman yang mendalam mengenai <strong>Empat Pilar MPR RI</strong>, yaitu <strong>Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika</strong>. Keempat pilar tersebut menjadi landasan penting dalam kehidupan berbangsa dan bernegara, khususnya bagi generasi muda sebagai calon pemimpin masa depan.</p><p>Dalam sambutannya, Ibu Anna Mu’awanah menekankan pentingnya peran pemuda dalam menjaga persatuan dan keutuhan bangsa di tengah tantangan zaman yang semakin kompleks. Menurutnya, pemuda tidak hanya dituntut cerdas secara intelektual, tetapi juga harus memiliki karakter kebangsaan yang kuat serta menjunjung tinggi nilai-nilai toleransi dan persatuan.</p><p>Kegiatan berlangsung secara interaktif dengan penyampaian materi yang komunikatif, sehingga mudah dipahami oleh para peserta. Para pemuda diajak untuk mengimplementasikan nilai-nilai Empat Pilar MPR RI dalam kehidupan sehari-hari, baik di lingkungan pendidikan, sosial, maupun dalam bermedia digital.</p><p>Melalui kegiatan Sosialisasi Empat Pilar MPR RI ini, diharapkan generasi muda semakin memiliki kesadaran berbangsa dan bernegara, serta mampu menjadi agen perubahan yang positif dalam menjaga persatuan dan kesatuan Negara Kesatuan Republik Indonesia.</p>\";s:12:\"published_at\";s:19:\"2026-02-10 16:08:35\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-10 09:09:02\";s:10:\"updated_at\";s:19:\"2026-02-10 09:10:25\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"dele