timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:7;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:4;s:7:\"user_id\";i:2;s:5:\"image\";s:47:\"posts/thumbnails/01KC4A0Q3Y658GP81P66NABMEY.jpg\";s:5:\"title\";s:75:\"Anna Mu’awanah : Membangun Generasi Berintegritas melalui Empat Pilar MPR\";s:4:\"slug\";s:70:\"anna-muawanah-membangun-generasi-berintegritas-melalui-empat-pilar-mpr\";s:4:\"body\";s:2580:\"<p>Tuban 9 Desember 2025– Anggota MPR RI, Anna Muawanah, menggelar kegiatan Sosialisasi Empat Pilar MPR RI pada siang hari di Kabupaten Tuban dengan mengusung tema “Membangun Generasi Berintegritas melalui Empat Pilar MPR”. Kegiatan ini diikuti oleh pelajar, mahasiswa, tokoh masyarakat, serta perwakilan pemuda dari berbagai kecamatan.<br>Dalam pemaparannya, Anna Muawanah menegaskan bahwa tantangan generasi muda saat ini tidak hanya soal pendidikan dan ekonomi, tetapi juga persoalan integritas, karakter, dan moralitas di tengah derasnya arus digitalisasi. Menurutnya, nilai-nilai dalam Empat Pilar MPR RI yakni Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika harus menjadi fondasi utama dalam membentuk kepribadian generasi bangsa.<br>“Generasi muda hari ini adalah penentu arah Indonesia ke depan. Jika integritas mereka kuat, maka bangsa ini akan kokoh. Empat Pilar bukan sekadar hafalan, tetapi harus diwujudkan dalam sikap jujur, bertanggung jawab, dan menghargai perbedaan,” ujar Anna di hadapan peserta.<br>Ia juga menyoroti maraknya praktik ketidakjujuran, penyalahgunaan media sosial, serta lunturnya etika dalam kehidupan bermasyarakat. Menurut Anna, penguatan nilai kebangsaan harus dimulai sejak dini agar generasi muda tidak mudah terpengaruh oleh paham radikal, hoaks, dan budaya instan yang merusak karakter.<br>“Kita ingin anak-anak muda Tuban menjadi generasi yang cerdas secara intelektual, kuat secara moral, dan tangguh dalam menghadapi tantangan global. Integritas adalah kunci untuk menciptakan pemimpin masa depan yang bersih dan berkomitmen untuk rakyat,” tegasnya.<br>Sementara itu, salah satu peserta sosialisasi, Ahmad Fauzi, mengaku kegiatan ini memberikan pemahaman baru tentang pentingnya peran pemuda dalam menjaga nilai kebangsaan. Ia menilai, selama ini banyak generasi muda yang kurang memahami makna Empat Pilar secara utuh.<br>“Setelah mengikuti sosialisasi ini, kami semakin sadar bahwa menjaga kejujuran, toleransi, dan cinta tanah air itu bukan hanya tugas pemerintah, tapi juga tanggung jawab kami sebagai pemuda,” ungkapnya.<br>Peserta lainnya juga berharap kegiatan serupa bisa terus dilakukan secara berkelanjutan, terutama di kalangan pelajar dan komunitas pemuda, agar nilai-nilai kebangsaan tidak hanya menjadi teori tetapi benar-benar dipraktikkan dalam kehidupan sehari-hari.<br>Melalui sosialisasi ini, Anna Muawanah berharap lahir generasi muda Tuban yang berintegritas, berkarakter kuat, serta mampu menjadi agen perubahan bagi kemajuan bangsa yang berlandaskan nilai-nilai luhur Empat Pilar MPR RI.</p>\";s:12:\"published_at\";s:19:\"2025-12-09 20:17:00\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2025-12-10 14:18:05\";s:10:\"updated_at\";s:19:\"2025-12-10 17:14:38\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:4;s:7:\"user_id\";i:2;s:5:\"image\";s:47:\"posts/thumbnails/01KC4A0Q3Y658GP81P66NABMEY.jpg\";s:5:\"t