INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('search_results_', 'O:42:\"Illuminate\\Pagination\\LengthAwarePaginator\":12:{s:8:\"\0*\0items\";O:39:\"Illuminate\\Database\\Eloquent\\Collection\":2:{s:8:\"\0*\0items\";a:10:{i:0;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:11;s:7:\"user_id\";i:3;s:5:\"image\";s:47:\"posts/thumbnails/01KVYNZ1A7G62H2XTTPTRX8FHP.jpg\";s:5:\"title\";s:102:\"Sosialisasi Empat Pilar MPR RI Bersama Dr. Hj. Anna Mu’awanah, S.E., M.H. di Politeknik MAPENA Tuban\";s:4:\"slug\";s:91:\"sosialisasi-empat-pilar-mpr-ri-bersama-dr-hj-anna-muawanah-se-mh-di-politeknik-mapena-tuban\";s:4:\"body\";s:3141:\"<p><strong>Tuban</strong> – Anggota MPR RI, Anna Mu\'awanah, menyelenggarakan kegiatan <strong>Sosialisasi Empat Pilar MPR RI</strong> yang bertempat di Aula Politeknik MAPENA Tuban. Kegiatan tersebut diikuti oleh perwakilan tokoh perempuan dari berbagai kecamatan di Kabupaten Tuban sebagai bagian dari upaya memperkuat pemahaman masyarakat terhadap nilai-nilai kebangsaan dan kehidupan bernegara.</p><p>Dalam sambutannya, Dr. Hj. Anna Mu’awanah, S.E., M.H. menyampaikan bahwa Empat Pilar MPR RI yang terdiri atas <strong>Pancasila sebagai Dasar dan Ideologi Negara, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika</strong> merupakan fondasi utama dalam menjaga persatuan dan kesatuan bangsa di tengah berbagai tantangan kehidupan bermasyarakat, berbangsa, dan bernegara.</p><p>Menurutnya, perempuan memiliki peran strategis dalam menanamkan nilai-nilai kebangsaan, toleransi, dan gotong royong, terutama dalam lingkungan keluarga dan masyarakat. Oleh karena itu, peningkatan pemahaman terhadap Empat Pilar MPR RI menjadi sangat penting agar perempuan dapat menjadi agen perubahan yang mampu memperkuat karakter bangsa dan menjaga harmonisasi sosial di tengah keberagaman.</p><p>“Perempuan merupakan madrasah pertama bagi generasi bangsa. Dari keluarga lahir nilai-nilai kebangsaan, toleransi, dan semangat persatuan yang harus terus dijaga. Karena itu, pemahaman terhadap Empat Pilar MPR RI menjadi bekal penting bagi para tokoh perempuan untuk berkontribusi dalam pembangunan bangsa,” ujar Anna Mu’awanah.</p><p>Dalam pemaparannya, Anna Mu’awanah menjelaskan bahwa Pancasila bukan hanya dasar negara, tetapi juga pedoman hidup yang harus diimplementasikan dalam kehidupan sehari-hari. Sementara itu, UUD NRI Tahun 1945 menjadi landasan konstitusional dalam penyelenggaraan negara yang menjamin hak dan kewajiban seluruh warga negara. Adapun NKRI merupakan bentuk negara yang harus terus dijaga keutuhannya, sedangkan Bhinneka Tunggal Ika menjadi perekat keberagaman suku, agama, budaya, dan golongan yang dimiliki Indonesia.</p><p>Kegiatan berlangsung secara interaktif dengan sesi dialog dan tanya jawab. Para peserta menyampaikan berbagai pandangan terkait peran perempuan dalam menjaga persatuan bangsa, meningkatkan partisipasi masyarakat dalam pembangunan, serta menghadapi tantangan sosial di era digital yang semakin kompleks.</p><p>Para peserta mengapresiasi penyelenggaraan kegiatan tersebut karena memberikan pemahaman yang lebih mendalam mengenai pentingnya penguatan wawasan kebangsaan. Mereka berharap kegiatan serupa dapat terus dilaksanakan secara berkelanjutan sehingga nilai-nilai Empat Pilar MPR RI semakin membumi dan menjadi pedoman dalam kehidupan masyarakat.</p><p>Melalui kegiatan Sosialisasi Empat Pilar MPR RI ini, diharapkan para tokoh perempuan Kabupaten Tuban dapat menjadi mitra strategis dalam memperkuat semangat nasionalisme, menjaga persatuan dan kesatuan bangsa, serta menanamkan nilai-nilai kebangsaan kepada generasi muda demi terwujudnya Indonesia yang maju, berdaulat, dan berkepribadian dalam kebudayaan.</p>\";s:12:\"published_at\";s:19:\"2026-06-17 20:00:17\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-06-25 06:02:36\";s:10:\"updated_at\";s:19:\"2026-06-25 06:02:36\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:11;s:7:\"user_id\";i:3;s:5:\"image\";s:47:\"posts/thumbnails/01KVYNZ1A7G62H2XTTPTRX8FHP.jpg\";s:5:\"title\";s:102:\"Sosialisasi Empat Pilar MPR RI Bersama Dr. Hj. Anna Mu’awanah, S.E., M.H. di Politeknik MAPENA Tuban\";s:4:\"slug\";s:91:\"sosialisasi-empat-pilar-mpr-ri-bersama-dr-hj-anna-muawanah-se-mh-di-politeknik-mapena-tuban\";s:4:\"body\";s:3141:\"<p><strong>Tuban</strong> – Anggota MPR RI, Anna Mu\'awanah, menyelenggarakan kegiatan <strong>Sosialisasi Empat Pilar MPR RI</strong> yang bertempat di Aula Politeknik MAPENA Tuban. Kegiatan tersebut diikuti oleh perwakilan tokoh perempuan dari berbagai kecamatan di Kabupaten Tuban sebagai bagian dari upaya memperkuat pemahaman masyarakat terhadap nilai-nilai kebangsaan dan kehidupan bernegara.</p><p>Dalam sambutannya, Dr. Hj. Anna Mu’awanah, S.E., M.H. menyampaikan bahwa Empat Pilar MPR RI yang terdiri atas <strong>Pancasila sebagai Dasar dan Ideologi Negara, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika</strong> merupakan fondasi utama dalam menjaga persatuan dan kesatuan bangsa di tengah berbagai tantangan kehidupan bermasyarakat, berbangsa, dan bernegara.</p><p>Menurutnya, perempuan memiliki peran strategis dalam menanamkan nilai-nilai kebangsaan, toleransi, dan gotong royong, terutama dalam lingkungan keluarga dan masyarakat. Oleh karena itu, peningkatan pemahaman terhadap Empat Pilar MPR RI menjadi sangat penting agar perempuan dapat menjadi agen perubahan yang mampu memperkuat karakter bangsa dan menjaga harmonisasi sosial di tengah keberagaman.</p><p>“Perempuan merupakan madrasah pertama bagi generasi bangsa. Dari keluarga lahir nilai-nilai kebangsaan, toleransi, dan semangat persatuan yang harus terus dijaga. Karena itu, pemahaman terhadap Empat Pilar MPR RI menjadi bekal penting bagi para tokoh perempuan untuk berkontribusi dalam pembangunan bangsa,” ujar Anna Mu’awanah.</p><p>Dalam pemaparannya, Anna Mu’awanah menjelaskan bahwa Pancasila bukan hanya dasar negara, tetapi juga pedoman hidup yang harus diimplementasikan dalam kehidupan sehari-hari. Sementara itu, UUD NRI Tahun 1945 menjadi landasan konstitusional dalam penyelenggaraan negara yang menjamin hak dan kewajiban seluruh warga negara. Adapun NKRI merupakan bentuk negara yang harus terus dijaga keutuhannya, sedangkan Bhinneka Tunggal Ika menjadi perekat keberagaman suku, agama, budaya, dan golongan yang dimiliki Indonesia.</p><p>Kegiatan berlangsung secara interaktif dengan sesi dialog dan tanya jawab. Para peserta menyampaikan berbagai pandangan terkait peran perempuan dalam menjaga persatuan bangsa, meningkatkan partisipasi masyarakat dalam pembangunan, serta menghadapi tantangan sosial di era digital yang semakin kompleks.</p><p>Para peserta mengapresiasi penyelenggaraan kegiatan tersebut karena memberikan pemahaman yang lebih mendalam mengenai pentingnya penguatan wawasan kebangsaan. Mereka berharap kegiatan serupa dapat terus dilaksanakan secara berkelanjutan sehingga nilai-nilai Empat Pilar MPR RI semakin membumi dan menjadi pedoman dalam kehidupan masyarakat.</p><p>Melalui kegiatan Sosialisasi Empat Pilar MPR RI ini, diharapkan para tokoh perempuan Kabupaten Tuban dapat menjadi mitra strategis dalam memperkuat semangat nasionalisme, menjaga persatuan dan kesatuan bangsa, serta menanamkan nilai-nilai kebangsaan kepada generasi muda demi terwujudnya Indonesia yang maju, berdaulat, dan berkepribadian dalam kebudayaan.</p>\";s:12:\"published_at\";s:19:\"2026-06-17 20:00:17\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-06-25 06:02:36\";s:10:\"updated_at\";s:19:\"2026-06-25 06:02:36\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:1;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:10;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KNGAVKWZQDZKMKSJT5TVF6CF.jpeg\";s:5:\"title\";s:120:\"Peran Perempuan dalam Menguatkan Nilai-Nilai Kebangsaan, DR. Anna Mu’awanah Sosialisasikan Empat Pilar MPR RI di Tuban\";s:4:\"slug\";s:115:\"peran-perempuan-dalam-menguatkan-nilai-nilai-kebangsaan-dr-anna-muawanah-sosialisasikan-empat-pilar-mpr-ri-di-tuban\";s:4:\"body\";s:2219:\"<p>Tuban – Dalam upaya memperkuat pemahaman nilai-nilai kebangsaan di tengah masyarakat, Dr. Anna Mu’awanah selaku Anggota MPR RI menggelar kegiatan Sosialisasi Empat Pilar MPR RI dengan mengusung tema <em>“Peran Perempuan dalam Menguatkan Nilai-Nilai Kebangsaan”</em>. Kegiatan ini dilaksanakan pada tanggal 4 April 2026 di Kabupaten Tuban, dengan melibatkan peserta dari kalangan perempuan, tokoh masyarakat, serta perwakilan organisasi perempuan setempat.</p><p>Dalam paparannya, Dr. Anna Mu’awanah menegaskan bahwa perempuan memiliki posisi strategis dalam menanamkan nilai-nilai kebangsaan, khususnya dalam lingkup keluarga sebagai unit terkecil dalam kehidupan berbangsa dan bernegara. Menurutnya, nilai-nilai yang terkandung dalam Empat Pilar MPR RI, yakni Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia, dan Bhinneka Tunggal Ika, harus terus diinternalisasikan dalam kehidupan sehari-hari.</p><p>“Perempuan adalah madrasah pertama bagi anak-anaknya. Dari tangan perempuanlah nilai-nilai Pancasila, semangat persatuan, serta sikap toleransi dan gotong royong dapat ditanamkan sejak dini,” ujar beliau.</p><p>Lebih lanjut, ia juga mengajak para peserta untuk menjadi agen perubahan di lingkungan masing-masing, terutama dalam menghadapi tantangan zaman seperti derasnya arus informasi digital, hoaks, serta potensi disintegrasi bangsa. Perempuan diharapkan mampu menjadi garda terdepan dalam menjaga harmoni sosial serta memperkuat persatuan di tengah keberagaman.</p><p>Kegiatan ini berlangsung dengan interaktif, di mana para peserta turut menyampaikan aspirasi, pandangan, serta pengalaman mereka terkait peran perempuan dalam menjaga nilai-nilai kebangsaan di lingkungan keluarga dan masyarakat. Aspirasi yang muncul di antaranya pentingnya peningkatan literasi digital bagi perempuan, penguatan pendidikan karakter, serta dukungan terhadap peran perempuan dalam pembangunan daerah.</p><p>Melalui kegiatan sosialisasi ini, diharapkan nilai-nilai Empat Pilar MPR RI semakin mengakar dalam kehidupan masyarakat, khususnya di kalangan perempuan, sehingga dapat menjadi fondasi kuat dalam menjaga keutuhan dan kedaulatan bangsa Indonesia.</p>\";s:12:\"published_at\";s:19:\"2026-04-04 09:42:38\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-04-06 02:42:59\";s:10:\"updated_at\";s:19:\"2026-04-06 02:44:56\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:10;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KNGAVKWZQDZKMKSJT5TVF6CF.jpeg\";s:5:\"title\";s:120:\"Peran Perempuan dalam Menguatkan Nilai-Nilai Kebangsaan, DR. Anna Mu’awanah Sosialisasikan Empat Pilar MPR RI di Tuban\";s:4:\"slug\";s:115:\"peran-perempuan-dalam-menguatkan-nilai-nilai-kebangsaan-dr-anna-muawanah-sosialisasikan-empat-pilar-mpr-ri-di-tuban\";s:4:\"body\";s:2219:\"<p>Tuban – Dalam upaya memperkuat pemahaman nilai-nilai kebangsaan di tengah masyarakat, Dr. Anna Mu’awanah selaku Anggota MPR RI menggelar kegiatan Sosialisasi Empat Pilar MPR RI dengan mengusung tema <em>“Peran Perempuan dalam Menguatkan Nilai-Nilai Kebangsaan”</em>. Kegiatan ini dilaksanakan pada tanggal 4 April 2026 di Kabupaten Tuban, dengan melibatkan peserta dari kalangan perempuan, tokoh masyarakat, serta perwakilan organisasi perempuan setempat.</p><p>Dalam paparannya, Dr. Anna Mu’awanah menegaskan bahwa perempuan memiliki posisi strategis dalam menanamkan nilai-nilai kebangsaan, khususnya dalam lingkup keluarga sebagai unit terkecil dalam kehidupan berbangsa dan bernegara. Menurutnya, nilai-nilai yang terkandung dalam Empat Pilar MPR RI, yakni Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia, dan Bhinneka Tunggal Ika, harus terus diinternalisasikan dalam kehidupan sehari-hari.</p><p>“Perempuan adalah madrasah pertama bagi anak-anaknya. Dari tangan perempuanlah nilai-nilai Pancasila, semangat persatuan, serta sikap toleransi dan gotong royong dapat ditanamkan sejak dini,” ujar beliau.</p><p>Lebih lanjut, ia juga mengajak para peserta untuk menjadi agen perubahan di lingkungan masing-masing, terutama dalam menghadapi tantangan zaman seperti derasnya arus informasi digital, hoaks, serta potensi disintegrasi bangsa. Perempuan diharapkan mampu menjadi garda terdepan dalam menjaga harmoni sosial serta memperkuat persatuan di tengah keberagaman.</p><p>Kegiatan ini berlangsung dengan interaktif, di mana para peserta turut menyampaikan aspirasi, pandangan, serta pengalaman mereka terkait peran perempuan dalam menjaga nilai-nilai kebangsaan di lingkungan keluarga dan masyarakat. Aspirasi yang muncul di antaranya pentingnya peningkatan literasi digital bagi perempuan, penguatan pendidikan karakter, serta dukungan terhadap peran perempuan dalam pembangunan daerah.</p><p>Melalui kegiatan sosialisasi ini, diharapkan nilai-nilai Empat Pilar MPR RI semakin mengakar dalam kehidupan masyarakat, khususnya di kalangan perempuan, sehingga dapat menjadi fondasi kuat dalam menjaga keutuhan dan kedaulatan bangsa Indonesia.</p>\";s:12:\"published_at\";s:19:\"2026-04-04 09:42:38\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-04-06 02:42:59\";s:10:\"updated_at\";s:19:\"2026-04-06 02:44:56\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:2;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:9;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KN1BX6JHE8JAZYC1D5NN01RK.jpeg\";s:5:\"title\";s:133:\"Peran Strategis Aktivis Perempuan dalam Penguatan Nilai Kebangsaan: Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu’awanah di Tuban\";s:4:\"slug\";s:128:\"peran-strategis-aktivis-perempuan-dalam-penguatan-nilai-kebangsaan-sosialisasi-empat-pilar-mpr-ri-oleh-dr-anna-muawanah-di-tuban\";s:4:\"body\";s:1586:\"<p>Kegiatan Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu\'awanah dilaksanakan pada tanggal 16 Maret 2026, bertempat di Aula Politeknik Pertanian Mapena (Poltana Mapena). Kegiatan ini dihadiri oleh perwakilan para aktivis perempuan se-Kabupaten Tuban yang memiliki peran penting dalam mendorong perubahan sosial di tengah masyarakat.<br><br></p><p>Dalam pemaparannya, Dr. Anna Mu’awanah menegaskan pentingnya pemahaman dan pengamalan Empat Pilar MPR RI, yakni Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika, sebagai fondasi utama dalam kehidupan berbangsa dan bernegara.<br><br></p><p>Beliau juga menekankan peran strategis para aktivis perempuan sebagai agen perubahan dalam memperkuat nilai-nilai kebangsaan, menjaga persatuan, serta mendorong terciptanya masyarakat yang inklusif dan berkeadilan. Dalam era dinamika sosial yang terus berkembang, perempuan diharapkan mampu menjadi penggerak dalam menanamkan nilai toleransi, kebhinekaan, dan semangat gotong royong di lingkungan masing-masing.<br><br></p><p>Kegiatan berlangsung interaktif melalui sesi diskusi dan tanya jawab, di mana para peserta aktif menyampaikan pandangan serta pengalaman terkait implementasi nilai-nilai kebangsaan dalam kehidupan sehari-hari.<br><br></p><p>Melalui kegiatan ini, diharapkan para aktivis perempuan semakin memahami dan menginternalisasi nilai-nilai Empat Pilar MPR RI, serta dapat berkontribusi secara nyata dalam menjaga keutuhan bangsa dan memperkuat karakter kebangsaan di tengah masyarakat.</p>\";s:12:\"published_at\";s:19:\"2026-03-16 14:13:00\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-03-31 07:14:40\";s:10:\"updated_at\";s:19:\"2026-03-31 07:14:50\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:9;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KN1BX6JHE8JAZYC1D5NN01RK.jpeg\";s:5:\"title\";s:133:\"Peran Strategis Aktivis Perempuan dalam Penguatan Nilai Kebangsaan: Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu’awanah di Tuban\";s:4:\"slug\";s:128:\"peran-strategis-aktivis-perempuan-dalam-penguatan-nilai-kebangsaan-sosialisasi-empat-pilar-mpr-ri-oleh-dr-anna-muawanah-di-tuban\";s:4:\"body\";s:1586:\"<p>Kegiatan Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu\'awanah dilaksanakan pada tanggal 16 Maret 2026, bertempat di Aula Politeknik Pertanian Mapena (Poltana Mapena). Kegiatan ini dihadiri oleh perwakilan para aktivis perempuan se-Kabupaten Tuban yang memiliki peran penting dalam mendorong perubahan sosial di tengah masyarakat.<br><br></p><p>Dalam pemaparannya, Dr. Anna Mu’awanah menegaskan pentingnya pemahaman dan pengamalan Empat Pilar MPR RI, yakni Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika, sebagai fondasi utama dalam kehidupan berbangsa dan bernegara.<br><br></p><p>Beliau juga menekankan peran strategis para aktivis perempuan sebagai agen perubahan dalam memperkuat nilai-nilai kebangsaan, menjaga persatuan, serta mendorong terciptanya masyarakat yang inklusif dan berkeadilan. Dalam era dinamika sosial yang terus berkembang, perempuan diharapkan mampu menjadi penggerak dalam menanamkan nilai toleransi, kebhinekaan, dan semangat gotong royong di lingkungan masing-masing.<br><br></p><p>Kegiatan berlangsung interaktif melalui sesi diskusi dan tanya jawab, di mana para peserta aktif menyampaikan pandangan serta pengalaman terkait implementasi nilai-nilai kebangsaan dalam kehidupan sehari-hari.<br><br></p><p>Melalui kegiatan ini, diharapkan para aktivis perempuan semakin memahami dan menginternalisasi nilai-nilai Empat Pilar MPR RI, serta dapat berkontribusi secara nyata dalam menjaga keutuhan bangsa dan memperkuat karakter kebangsaan di tengah masyarakat.</p>\";s:12:\"published_at\";s:19:\"2026-03-16 14:13:00\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-03-31 07:14:40\";s:10:\"updated_at\";s:19:\"2026-03-31 07:14:50\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:3;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:8;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KN1BP1M90THBX12K56TYMD1C.HEIC\";s:5:\"title\";s:123:\"Penguatan Peran Perempuan dalam Menjaga Nilai Kebangsaan: Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu’awanah di Tuban\";s:4:\"slug\";s:118:\"penguatan-peran-perempuan-dalam-menjaga-nilai-kebangsaan-sosialisasi-empat-pilar-mpr-ri-oleh-dr-anna-muawanah-di-tuban\";s:4:\"body\";s:1404:\"<p>Kegiatan Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu\'awanah telah dilaksanakan pada tanggal 14 Maret 2026, bertempat di Aula Politeknik Pertanian Mapena (Poltana Mapena). Kegiatan ini dihadiri oleh perwakilan tokoh perempuan se-Kabupaten Tuban yang aktif dalam berbagai bidang sosial dan kemasyarakatan.<br><br></p><p>Dalam pemaparannya, Dr. Anna Mu’awanah menekankan pentingnya pemahaman dan pengamalan Empat Pilar MPR RI, yakni Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika, sebagai landasan utama dalam kehidupan berbangsa dan bernegara.<br>Beliau juga menyoroti peran strategis perempuan sebagai agen perubahan dalam memperkuat nilai-nilai kebangsaan di lingkungan keluarga dan masyarakat. Melalui peran tersebut, perempuan diharapkan mampu menjadi garda terdepan dalam menjaga persatuan, menanamkan nilai toleransi, serta membangun karakter generasi bangsa.<br><br></p><p>Kegiatan berlangsung secara interaktif dengan sesi diskusi dan tanya jawab, di mana para peserta menyampaikan berbagai pandangan dan pengalaman terkait implementasi nilai-nilai kebangsaan dalam kehidupan sehari-hari.<br>Melalui sosialisasi ini, diharapkan para tokoh perempuan semakin memahami dan menginternalisasi nilai-nilai Empat Pilar MPR RI, serta berkontribusi aktif dalam menjaga keutuhan dan keharmonisan bangsa.</p>\";s:12:\"published_at\";s:19:\"2026-03-14 14:08:00\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-03-31 07:10:46\";s:10:\"updated_at\";s:19:\"2026-03-31 07:11:24\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:8;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KN1BP1M90THBX12K56TYMD1C.HEIC\";s:5:\"title\";s:123:\"Penguatan Peran Perempuan dalam Menjaga Nilai Kebangsaan: Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu’awanah di Tuban\";s:4:\"slug\";s:118:\"penguatan-peran-perempuan-dalam-menjaga-nilai-kebangsaan-sosialisasi-empat-pilar-mpr-ri-oleh-dr-anna-muawanah-di-tuban\";s:4:\"body\";s:1404:\"<p>Kegiatan Sosialisasi Empat Pilar MPR RI oleh Dr. Anna Mu\'awanah telah dilaksanakan pada tanggal 14 Maret 2026, bertempat di Aula Politeknik Pertanian Mapena (Poltana Mapena). Kegiatan ini dihadiri oleh perwakilan tokoh perempuan se-Kabupaten Tuban yang aktif dalam berbagai bidang sosial dan kemasyarakatan.<br><br></p><p>Dalam pemaparannya, Dr. Anna Mu’awanah menekankan pentingnya pemahaman dan pengamalan Empat Pilar MPR RI, yakni Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika, sebagai landasan utama dalam kehidupan berbangsa dan bernegara.<br>Beliau juga menyoroti peran strategis perempuan sebagai agen perubahan dalam memperkuat nilai-nilai kebangsaan di lingkungan keluarga dan masyarakat. Melalui peran tersebut, perempuan diharapkan mampu menjadi garda terdepan dalam menjaga persatuan, menanamkan nilai toleransi, serta membangun karakter generasi bangsa.<br><br></p><p>Kegiatan berlangsung secara interaktif dengan sesi diskusi dan tanya jawab, di mana para peserta menyampaikan berbagai pandangan dan pengalaman terkait implementasi nilai-nilai kebangsaan dalam kehidupan sehari-hari.<br>Melalui sosialisasi ini, diharapkan para tokoh perempuan semakin memahami dan menginternalisasi nilai-nilai Empat Pilar MPR RI, serta berkontribusi aktif dalam menjaga keutuhan dan keharmonisan bangsa.</p>\";s:12:\"published_at\";s:19:\"2026-03-14 14:08:00\";s:8:\"featured\";i:0;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-03-31 07:10:46\";s:10:\"updated_at\";s:19:\"2026-03-31 07:11:24\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:4;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:7;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KJ83QT2ADFKDM3DHANA4H0CM.jpeg\";s:5:\"title\";s:35:\"Malam Keakraban (Makrab) SISKOMFEST\";s:4:\"slug\";s:33:\"malam-keakraban-makrab-siskomfest\";s:4:\"body\";s:1349:\"<p><strong>Kegiatan Malam Keakraban (Makrab) SISKOMFEST</strong> yang dilaksanakan pada tanggal 14–15 Januari 2026 di Pantai Semilir diikuti oleh 66 peserta yang merupakan mahasiswa Program Studi Sistem Komputer angkatan 2023, 2024, dan 2025. Kegiatan ini turut dihadiri oleh Kepala Program Studi Sistem Komputer, Dwi Issadari Hastuti, S.Pd., S.Kom., M.Kom., serta Ketua Himpunan Mahasiswa Sistem Komputer yang mendampingi jalannya kegiatan.<br><br>Dalam sambutannya, Abdul Ghofur menyampaikan harapannya agar kegiatan Makrab ini dapat menjadi dasar terbentuknya solidaritas yang kuat antar mahasiswa Sistem Komputer lintas angkatan. Selain itu, kegiatan ini juga diharapkan menjadi wadah bagi mahasiswa untuk berkembang, serta sebagai sarana perkenalan organisasi Program Studi kepada mahasiswa baru agar lebih mengenal lingkungan akademik dan organisasi kemahasiswaan.<br><br>Sementara itu, Ibu Dwi Issadari Hastuti juga menyampaikan harapan besar agar dengan terselenggaranya kegiatan Makrab SISKOMFEST ini, tali silaturahmi antar mahasiswa, dosen, dan seluruh civitas akademika Program Studi Sistem Komputer dapat terus terjaga, tidak terputus, serta semakin kuat dan kompak. Beliau berharap kegiatan ini dapat terus dikembangkan di masa mendatang agar semakin baik dan memberikan dampak positif bagi mahasiswa Sistem Komputer ke depannya.</p>\";s:12:\"published_at\";s:19:\"2026-02-23 22:08:55\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-24 15:19:31\";s:10:\"updated_at\";s:19:\"2026-02-24 15:19:31\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:7;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KJ83QT2ADFKDM3DHANA4H0CM.jpeg\";s:5:\"title\";s:35:\"Malam Keakraban (Makrab) SISKOMFEST\";s:4:\"slug\";s:33:\"malam-keakraban-makrab-siskomfest\";s:4:\"body\";s:1349:\"<p><strong>Kegiatan Malam Keakraban (Makrab) SISKOMFEST</strong> yang dilaksanakan pada tanggal 14–15 Januari 2026 di Pantai Semilir diikuti oleh 66 peserta yang merupakan mahasiswa Program Studi Sistem Komputer angkatan 2023, 2024, dan 2025. Kegiatan ini turut dihadiri oleh Kepala Program Studi Sistem Komputer, Dwi Issadari Hastuti, S.Pd., S.Kom., M.Kom., serta Ketua Himpunan Mahasiswa Sistem Komputer yang mendampingi jalannya kegiatan.<br><br>Dalam sambutannya, Abdul Ghofur menyampaikan harapannya agar kegiatan Makrab ini dapat menjadi dasar terbentuknya solidaritas yang kuat antar mahasiswa Sistem Komputer lintas angkatan. Selain itu, kegiatan ini juga diharapkan menjadi wadah bagi mahasiswa untuk berkembang, serta sebagai sarana perkenalan organisasi Program Studi kepada mahasiswa baru agar lebih mengenal lingkungan akademik dan organisasi kemahasiswaan.<br><br>Sementara itu, Ibu Dwi Issadari Hastuti juga menyampaikan harapan besar agar dengan terselenggaranya kegiatan Makrab SISKOMFEST ini, tali silaturahmi antar mahasiswa, dosen, dan seluruh civitas akademika Program Studi Sistem Komputer dapat terus terjaga, tidak terputus, serta semakin kuat dan kompak. Beliau berharap kegiatan ini dapat terus dikembangkan di masa mendatang agar semakin baik dan memberikan dampak positif bagi mahasiswa Sistem Komputer ke depannya.</p>\";s:12:\"published_at\";s:19:\"2026-02-23 22:08:55\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-24 15:19:31\";s:10:\"updated_at\";s:19:\"2026-02-24 15:19:31\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:5;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:6;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KH3CZC5PTA4KXG9H8JDCM672.jpeg\";s:5:\"title\";s:77:\"Ibu Anna Mu’awanah Gelar Sosialisasi Empat Pilar MPR RI untuk Generasi Muda\";s:4:\"slug\";s:74:\"ibu-anna-muawanah-gelar-sosialisasi-empat-pilar-mpr-ri-untuk-generasi-muda\";s:4:\"body\";s:1723:\"<p>Tuban - Dalam rangka memperkuat wawasan kebangsaan di kalangan generasi muda, <strong>Ibu Anna Mu’awanah</strong> menyelenggarakan kegiatan <strong>Sosialisasi Empat Pilar MPR RI</strong> pada <strong>Selasa, 10 Februari 2026</strong>. Kegiatan ini diikuti oleh <strong>pemuda dan pemudi</strong> dari berbagai latar belakang dengan antusiasme yang tinggi.</p><p>Sosialisasi ini bertujuan untuk menanamkan pemahaman yang mendalam mengenai <strong>Empat Pilar MPR RI</strong>, yaitu <strong>Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika</strong>. Keempat pilar tersebut menjadi landasan penting dalam kehidupan berbangsa dan bernegara, khususnya bagi generasi muda sebagai calon pemimpin masa depan.</p><p>Dalam sambutannya, Ibu Anna Mu’awanah menekankan pentingnya peran pemuda dalam menjaga persatuan dan keutuhan bangsa di tengah tantangan zaman yang semakin kompleks. Menurutnya, pemuda tidak hanya dituntut cerdas secara intelektual, tetapi juga harus memiliki karakter kebangsaan yang kuat serta menjunjung tinggi nilai-nilai toleransi dan persatuan.</p><p>Kegiatan berlangsung secara interaktif dengan penyampaian materi yang komunikatif, sehingga mudah dipahami oleh para peserta. Para pemuda diajak untuk mengimplementasikan nilai-nilai Empat Pilar MPR RI dalam kehidupan sehari-hari, baik di lingkungan pendidikan, sosial, maupun dalam bermedia digital.</p><p>Melalui kegiatan Sosialisasi Empat Pilar MPR RI ini, diharapkan generasi muda semakin memiliki kesadaran berbangsa dan bernegara, serta mampu menjadi agen perubahan yang positif dalam menjaga persatuan dan kesatuan Negara Kesatuan Republik Indonesia.</p>\";s:12:\"published_at\";s:19:\"2026-02-10 16:08:35\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-10 09:09:02\";s:10:\"updated_at\";s:19:\"2026-02-10 09:10:25\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:6;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KH3CZC5PTA4KXG9H8JDCM672.jpeg\";s:5:\"title\";s:77:\"Ibu Anna Mu’awanah Gelar Sosialisasi Empat Pilar MPR RI untuk Generasi Muda\";s:4:\"slug\";s:74:\"ibu-anna-muawanah-gelar-sosialisasi-empat-pilar-mpr-ri-untuk-generasi-muda\";s:4:\"body\";s:1723:\"<p>Tuban - Dalam rangka memperkuat wawasan kebangsaan di kalangan generasi muda, <strong>Ibu Anna Mu’awanah</strong> menyelenggarakan kegiatan <strong>Sosialisasi Empat Pilar MPR RI</strong> pada <strong>Selasa, 10 Februari 2026</strong>. Kegiatan ini diikuti oleh <strong>pemuda dan pemudi</strong> dari berbagai latar belakang dengan antusiasme yang tinggi.</p><p>Sosialisasi ini bertujuan untuk menanamkan pemahaman yang mendalam mengenai <strong>Empat Pilar MPR RI</strong>, yaitu <strong>Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), serta Bhinneka Tunggal Ika</strong>. Keempat pilar tersebut menjadi landasan penting dalam kehidupan berbangsa dan bernegara, khususnya bagi generasi muda sebagai calon pemimpin masa depan.</p><p>Dalam sambutannya, Ibu Anna Mu’awanah menekankan pentingnya peran pemuda dalam menjaga persatuan dan keutuhan bangsa di tengah tantangan zaman yang semakin kompleks. Menurutnya, pemuda tidak hanya dituntut cerdas secara intelektual, tetapi juga harus memiliki karakter kebangsaan yang kuat serta menjunjung tinggi nilai-nilai toleransi dan persatuan.</p><p>Kegiatan berlangsung secara interaktif dengan penyampaian materi yang komunikatif, sehingga mudah dipahami oleh para peserta. Para pemuda diajak untuk mengimplementasikan nilai-nilai Empat Pilar MPR RI dalam kehidupan sehari-hari, baik di lingkungan pendidikan, sosial, maupun dalam bermedia digital.</p><p>Melalui kegiatan Sosialisasi Empat Pilar MPR RI ini, diharapkan generasi muda semakin memiliki kesadaran berbangsa dan bernegara, serta mampu menjadi agen perubahan yang positif dalam menjaga persatuan dan kesatuan Negara Kesatuan Republik Indonesia.</p>\";s:12:\"published_at\";s:19:\"2026-02-10 16:08:35\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-10 09:09:02\";s:10:\"updated_at\";s:19:\"2026-02-10 09:10:25\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:6;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:5;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KH0F54N4JZ8KT3MKBSJ9T9WS.jpeg\";s:5:\"title\";s:68:\"Anna Mu’awanah Ajak Para Pemuda Memperkuat Nilai-Nilai Kebangsaan.\";s:4:\"slug\";s:64:\"anna-muawanah-ajak-para-pemuda-memperkuat-nilai-nilai-kebangsaan\";s:4:\"body\";s:1490:\"<p>Tuban, 07 Februari 2026 — Anggota DPR RI sekaligus MPR RI, Anna Mu’awanah, menggelar kegiatan Sosialisasi Empat Pilar Kebangsaan. Kegiatan ini dihadiri oleh Para Tokoh Pemuda.</p><p>&nbsp;</p><p>Dalam pemaparannya, Anna Mu’awanah menyoroti berbagai permasalahan kebangsaan yang semakin kompleks di tahun 2026, yakni perkembangan politik global yang semankin tidak menentu.</p><p>Maka dari Itu Anna Mu\'awanah menyampaikan agar masyarakat menjaga kesatuan dan persatuan serta pentingnya penguatan nilai-nilai Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika sebagai pedoman hidup berbangsa dan bernegara.&nbsp;</p><p>&nbsp;</p><p>Ibu Anna menambahkan, bahwa Ibu Anna sangat mengharapkan agar apa yang telah di sosialisasikan hari ini bisa diterapkan dalam kehidupan sehari-hari di masyarakat luas sehingga kita bisa melindungi generasi muda dari gangguan apapun yang dapat memecah belah bangsa.</p><p>&nbsp;</p><p>Kegiatan sosialisasi ini berlangsung secara dialogis dan partisipatif. Para peserta yang terdiri dari tokoh pemuda terlihat antusias mengikuti pemaparan materi serta berdiskusi mengenai peran masyarakat dalam mengamalkan nilai-nilai Pancasila dan semangat kebangsaan.</p><p>&nbsp;</p><p>Melalui kegiatan Sosialisasi Empat Pilar Kebangsaan ini Ibu Anna berharap pemahaman masyarakat terutama para pemuda terhadap nilai-nilai kebangsaan semakin meningkat dan mampu memperkokoh persatuan bangsa dalam mewujudkan Indonesia yang berdaulat, mandiri dan berkepribadian.</p>\";s:12:\"published_at\";s:19:\"2026-02-07 12:48:41\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-09 05:49:25\";s:10:\"updated_at\";s:19:\"2026-02-24 15:03:21\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:5;s:7:\"user_id\";i:3;s:5:\"image\";s:48:\"posts/thumbnails/01KH0F54N4JZ8KT3MKBSJ9T9WS.jpeg\";s:5:\"title\";s:68:\"Anna Mu’awanah Ajak Para Pemuda Memperkuat Nilai-Nilai Kebangsaan.\";s:4:\"slug\";s:64:\"anna-muawanah-ajak-para-pemuda-memperkuat-nilai-nilai-kebangsaan\";s:4:\"body\";s:1490:\"<p>Tuban, 07 Februari 2026 — Anggota DPR RI sekaligus MPR RI, Anna Mu’awanah, menggelar kegiatan Sosialisasi Empat Pilar Kebangsaan. Kegiatan ini dihadiri oleh Para Tokoh Pemuda.</p><p>&nbsp;</p><p>Dalam pemaparannya, Anna Mu’awanah menyoroti berbagai permasalahan kebangsaan yang semakin kompleks di tahun 2026, yakni perkembangan politik global yang semankin tidak menentu.</p><p>Maka dari Itu Anna Mu\'awanah menyampaikan agar masyarakat menjaga kesatuan dan persatuan serta pentingnya penguatan nilai-nilai Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika sebagai pedoman hidup berbangsa dan bernegara.&nbsp;</p><p>&nbsp;</p><p>Ibu Anna menambahkan, bahwa Ibu Anna sangat mengharapkan agar apa yang telah di sosialisasikan hari ini bisa diterapkan dalam kehidupan sehari-hari di masyarakat luas sehingga kita bisa melindungi generasi muda dari gangguan apapun yang dapat memecah belah bangsa.</p><p>&nbsp;</p><p>Kegiatan sosialisasi ini berlangsung secara dialogis dan partisipatif. Para peserta yang terdiri dari tokoh pemuda terlihat antusias mengikuti pemaparan materi serta berdiskusi mengenai peran masyarakat dalam mengamalkan nilai-nilai Pancasila dan semangat kebangsaan.</p><p>&nbsp;</p><p>Melalui kegiatan Sosialisasi Empat Pilar Kebangsaan ini Ibu Anna berharap pemahaman masyarakat terutama para pemuda terhadap nilai-nilai kebangsaan semakin meningkat dan mampu memperkokoh persatuan bangsa dalam mewujudkan Indonesia yang berdaulat, mandiri dan berkepribadian.</p>\";s:12:\"published_at\";s:19:\"2026-02-07 12:48:41\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2026-02-09 05:49:25\";s:10:\"updated_at\";s:19:\"2026-02-24 15:03:21\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:7;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:4;s:7:\"user_id\";i:2;s:5:\"image\";s:47:\"posts/thumbnails/01KC4A0Q3Y658GP81P66NABMEY.jpg\";s:5:\"title\";s:75:\"Anna Mu’awanah : Membangun Generasi Berintegritas melalui Empat Pilar MPR\";s:4:\"slug\";s:70:\"anna-muawanah-membangun-generasi-berintegritas-melalui-empat-pilar-mpr\";s:4:\"body\";s:2580:\"<p>Tuban 9 Desember 2025– Anggota MPR RI, Anna Muawanah, menggelar kegiatan Sosialisasi Empat Pilar MPR RI pada siang hari di Kabupaten Tuban dengan mengusung tema “Membangun Generasi Berintegritas melalui Empat Pilar MPR”. Kegiatan ini diikuti oleh pelajar, mahasiswa, tokoh masyarakat, serta perwakilan pemuda dari berbagai kecamatan.<br>Dalam pemaparannya, Anna Muawanah menegaskan bahwa tantangan generasi muda saat ini tidak hanya soal pendidikan dan ekonomi, tetapi juga persoalan integritas, karakter, dan moralitas di tengah derasnya arus digitalisasi. Menurutnya, nilai-nilai dalam Empat Pilar MPR RI yakni Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika harus menjadi fondasi utama dalam membentuk kepribadian generasi bangsa.<br>“Generasi muda hari ini adalah penentu arah Indonesia ke depan. Jika integritas mereka kuat, maka bangsa ini akan kokoh. Empat Pilar bukan sekadar hafalan, tetapi harus diwujudkan dalam sikap jujur, bertanggung jawab, dan menghargai perbedaan,” ujar Anna di hadapan peserta.<br>Ia juga menyoroti maraknya praktik ketidakjujuran, penyalahgunaan media sosial, serta lunturnya etika dalam kehidupan bermasyarakat. Menurut Anna, penguatan nilai kebangsaan harus dimulai sejak dini agar generasi muda tidak mudah terpengaruh oleh paham radikal, hoaks, dan budaya instan yang merusak karakter.<br>“Kita ingin anak-anak muda Tuban menjadi generasi yang cerdas secara intelektual, kuat secara moral, dan tangguh dalam menghadapi tantangan global. Integritas adalah kunci untuk menciptakan pemimpin masa depan yang bersih dan berkomitmen untuk rakyat,” tegasnya.<br>Sementara itu, salah satu peserta sosialisasi, Ahmad Fauzi, mengaku kegiatan ini memberikan pemahaman baru tentang pentingnya peran pemuda dalam menjaga nilai kebangsaan. Ia menilai, selama ini banyak generasi muda yang kurang memahami makna Empat Pilar secara utuh.<br>“Setelah mengikuti sosialisasi ini, kami semakin sadar bahwa menjaga kejujuran, toleransi, dan cinta tanah air itu bukan hanya tugas pemerintah, tapi juga tanggung jawab kami sebagai pemuda,” ungkapnya.<br>Peserta lainnya juga berharap kegiatan serupa bisa terus dilakukan secara berkelanjutan, terutama di kalangan pelajar dan komunitas pemuda, agar nilai-nilai kebangsaan tidak hanya menjadi teori tetapi benar-benar dipraktikkan dalam kehidupan sehari-hari.<br>Melalui sosialisasi ini, Anna Muawanah berharap lahir generasi muda Tuban yang berintegritas, berkarakter kuat, serta mampu menjadi agen perubahan bagi kemajuan bangsa yang berlandaskan nilai-nilai luhur Empat Pilar MPR RI.</p>\";s:12:\"published_at\";s:19:\"2025-12-09 20:17:00\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2025-12-10 14:18:05\";s:10:\"updated_at\";s:19:\"2025-12-10 17:14:38\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:4;s:7:\"user_id\";i:2;s:5:\"image\";s:47:\"posts/thumbnails/01KC4A0Q3Y658GP81P66NABMEY.jpg\";s:5:\"title\";s:75:\"Anna Mu’awanah : Membangun Generasi Berintegritas melalui Empat Pilar MPR\";s:4:\"slug\";s:70:\"anna-muawanah-membangun-generasi-berintegritas-melalui-empat-pilar-mpr\";s:4:\"body\";s:2580:\"<p>Tuban 9 Desember 2025– Anggota MPR RI, Anna Muawanah, menggelar kegiatan Sosialisasi Empat Pilar MPR RI pada siang hari di Kabupaten Tuban dengan mengusung tema “Membangun Generasi Berintegritas melalui Empat Pilar MPR”. Kegiatan ini diikuti oleh pelajar, mahasiswa, tokoh masyarakat, serta perwakilan pemuda dari berbagai kecamatan.<br>Dalam pemaparannya, Anna Muawanah menegaskan bahwa tantangan generasi muda saat ini tidak hanya soal pendidikan dan ekonomi, tetapi juga persoalan integritas, karakter, dan moralitas di tengah derasnya arus digitalisasi. Menurutnya, nilai-nilai dalam Empat Pilar MPR RI yakni Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika harus menjadi fondasi utama dalam membentuk kepribadian generasi bangsa.<br>“Generasi muda hari ini adalah penentu arah Indonesia ke depan. Jika integritas mereka kuat, maka bangsa ini akan kokoh. Empat Pilar bukan sekadar hafalan, tetapi harus diwujudkan dalam sikap jujur, bertanggung jawab, dan menghargai perbedaan,” ujar Anna di hadapan peserta.<br>Ia juga menyoroti maraknya praktik ketidakjujuran, penyalahgunaan media sosial, serta lunturnya etika dalam kehidupan bermasyarakat. Menurut Anna, penguatan nilai kebangsaan harus dimulai sejak dini agar generasi muda tidak mudah terpengaruh oleh paham radikal, hoaks, dan budaya instan yang merusak karakter.<br>“Kita ingin anak-anak muda Tuban menjadi generasi yang cerdas secara intelektual, kuat secara moral, dan tangguh dalam menghadapi tantangan global. Integritas adalah kunci untuk menciptakan pemimpin masa depan yang bersih dan berkomitmen untuk rakyat,” tegasnya.<br>Sementara itu, salah satu peserta sosialisasi, Ahmad Fauzi, mengaku kegiatan ini memberikan pemahaman baru tentang pentingnya peran pemuda dalam menjaga nilai kebangsaan. Ia menilai, selama ini banyak generasi muda yang kurang memahami makna Empat Pilar secara utuh.<br>“Setelah mengikuti sosialisasi ini, kami semakin sadar bahwa menjaga kejujuran, toleransi, dan cinta tanah air itu bukan hanya tugas pemerintah, tapi juga tanggung jawab kami sebagai pemuda,” ungkapnya.<br>Peserta lainnya juga berharap kegiatan serupa bisa terus dilakukan secara berkelanjutan, terutama di kalangan pelajar dan komunitas pemuda, agar nilai-nilai kebangsaan tidak hanya menjadi teori tetapi benar-benar dipraktikkan dalam kehidupan sehari-hari.<br>Melalui sosialisasi ini, Anna Muawanah berharap lahir generasi muda Tuban yang berintegritas, berkarakter kuat, serta mampu menjadi agen perubahan bagi kemajuan bangsa yang berlandaskan nilai-nilai luhur Empat Pilar MPR RI.</p>\";s:12:\"published_at\";s:19:\"2025-12-09 20:17:00\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2025-12-10 14:18:05\";s:10:\"updated_at\";s:19:\"2025-12-10 17:14:38\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:8;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:3;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KC3AQNPWP50X2KCPA2RS9KVY.jpeg\";s:5:\"title\";s:97:\"Sosialisasi Empat Pilar MPR RI : Penguatan Karakter Bangsa melalui Sosialisasi Empat Pilar MPR RI\";s:4:\"slug\";s:95:\"sosialisasi-empat-pilar-mpr-ri-penguatan-karakter-bangsa-melalui-sosialisasi-empat-pilar-mpr-ri\";s:4:\"body\";s:2874:\"<p>TUBAN 9 Desember 2025– Anggota DPR RI sekaligus MPR RI, Anna Mu’awanah, menggelar kegiatan Sosialisasi Empat Pilar MPR RI pada malam hari di Kabupaten Tuban, dengan mengusung tema “Penguatan Karakter Bangsa melalui Sosialisasi Empat Pilar MPR RI”. Kegiatan ini diikuti oleh ratusan peserta dari berbagai unsur masyarakat, mulai dari pemuda, tokoh masyarakat, hingga perwakilan organisasi kemasyarakatan.<br>Dalam pemaparannya, Anna Mu’awanah menegaskan bahwa tantangan kebangsaan saat ini tidak hanya soal ekonomi dan politik, tetapi juga krisis karakter dan nilai moral, khususnya di kalangan generasi muda. Menurutnya, derasnya arus globalisasi dan perkembangan teknologi digital membawa dampak besar terhadap pola pikir dan perilaku masyarakat.<br>“Empat Pilar Kebangsaan—Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika—bukan sekadar hafalan, tetapi harus menjadi pedoman hidup dalam bersikap dan berperilaku. Jika karakter bangsa kita kuat, maka bangsa ini akan mampu menghadapi tantangan apa pun,” tegas Anna mu\'awanah di hadapan peserta.<br>Ia juga menekankan pentingnya menanamkan nilai kejujuran, gotong royong, toleransi, serta tanggung jawab sosial sejak dini. Anna mu\'awanah menilai bahwa penguatan karakter tidak cukup dilakukan di sekolah saja, tetapi harus menjadi gerakan bersama di lingkungan keluarga, masyarakat, dan pemerintah.<br>“Saat ini kita dihadapkan pada persoalan lunturnya etika, rendahnya kepedulian sosial, serta meningkatnya konflik akibat perbedaan. Di sinilah peran Empat Pilar sebagai perekat persatuan bangsa sangat penting untuk terus disosialisasikan,” tambahnya.<br>Para peserta menyambut kegiatan ini dengan antusias. Salah satu peserta, perwakilan tokoh pemuda Tuban, menyampaikan bahwa sosialisasi ini membuka kembali kesadaran akan pentingnya nilai-nilai kebangsaan di tengah kehidupan modern yang serba instan.<br>“Kami sebagai generasi muda sering kali lebih sibuk dengan media sosial dan urusan pribadi. Kegiatan seperti ini mengingatkan kami bahwa karakter dan nasionalisme tetap menjadi fondasi utama dalam membangun masa depan bangsa,” ujarnya.<br>Peserta lainnya juga menilai bahwa materi yang disampaikan relevan dengan kondisi masyarakat saat ini, khususnya dalam menghadapi maraknya hoaks, konflik sosial, dan menurunnya rasa saling menghormati.<br>Melalui sosialisasi ini, Anna Mu’awanah berharap nilai-nilai Empat Pilar tidak hanya dipahami secara teoritis, tetapi benar-benar diimplementasikan dalam kehidupan sehari-hari. Ia juga mengajak seluruh elemen masyarakat Tuban untuk ikut menjadi agen penguatan karakter bangsa di lingkungannya masing-masing.<br>Kegiatan sosialisasi yang berlangsung hingga siang hari tersebut ditutup dengan sesi dialog interaktif antara peserta dan narasumber, yang membahas berbagai persoalan kebangsaan dan tantangan karakter bangsa di era digital.</p>\";s:12:\"published_at\";s:19:\"2025-12-09 12:11:02\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2025-12-10 05:11:23\";s:10:\"updated_at\";s:19:\"2025-12-10 14:29:58\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:3;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KC3AQNPWP50X2KCPA2RS9KVY.jpeg\";s:5:\"title\";s:97:\"Sosialisasi Empat Pilar MPR RI : Penguatan Karakter Bangsa melalui Sosialisasi Empat Pilar MPR RI\";s:4:\"slug\";s:95:\"sosialisasi-empat-pilar-mpr-ri-penguatan-karakter-bangsa-melalui-sosialisasi-empat-pilar-mpr-ri\";s:4:\"body\";s:2874:\"<p>TUBAN 9 Desember 2025– Anggota DPR RI sekaligus MPR RI, Anna Mu’awanah, menggelar kegiatan Sosialisasi Empat Pilar MPR RI pada malam hari di Kabupaten Tuban, dengan mengusung tema “Penguatan Karakter Bangsa melalui Sosialisasi Empat Pilar MPR RI”. Kegiatan ini diikuti oleh ratusan peserta dari berbagai unsur masyarakat, mulai dari pemuda, tokoh masyarakat, hingga perwakilan organisasi kemasyarakatan.<br>Dalam pemaparannya, Anna Mu’awanah menegaskan bahwa tantangan kebangsaan saat ini tidak hanya soal ekonomi dan politik, tetapi juga krisis karakter dan nilai moral, khususnya di kalangan generasi muda. Menurutnya, derasnya arus globalisasi dan perkembangan teknologi digital membawa dampak besar terhadap pola pikir dan perilaku masyarakat.<br>“Empat Pilar Kebangsaan—Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika—bukan sekadar hafalan, tetapi harus menjadi pedoman hidup dalam bersikap dan berperilaku. Jika karakter bangsa kita kuat, maka bangsa ini akan mampu menghadapi tantangan apa pun,” tegas Anna mu\'awanah di hadapan peserta.<br>Ia juga menekankan pentingnya menanamkan nilai kejujuran, gotong royong, toleransi, serta tanggung jawab sosial sejak dini. Anna mu\'awanah menilai bahwa penguatan karakter tidak cukup dilakukan di sekolah saja, tetapi harus menjadi gerakan bersama di lingkungan keluarga, masyarakat, dan pemerintah.<br>“Saat ini kita dihadapkan pada persoalan lunturnya etika, rendahnya kepedulian sosial, serta meningkatnya konflik akibat perbedaan. Di sinilah peran Empat Pilar sebagai perekat persatuan bangsa sangat penting untuk terus disosialisasikan,” tambahnya.<br>Para peserta menyambut kegiatan ini dengan antusias. Salah satu peserta, perwakilan tokoh pemuda Tuban, menyampaikan bahwa sosialisasi ini membuka kembali kesadaran akan pentingnya nilai-nilai kebangsaan di tengah kehidupan modern yang serba instan.<br>“Kami sebagai generasi muda sering kali lebih sibuk dengan media sosial dan urusan pribadi. Kegiatan seperti ini mengingatkan kami bahwa karakter dan nasionalisme tetap menjadi fondasi utama dalam membangun masa depan bangsa,” ujarnya.<br>Peserta lainnya juga menilai bahwa materi yang disampaikan relevan dengan kondisi masyarakat saat ini, khususnya dalam menghadapi maraknya hoaks, konflik sosial, dan menurunnya rasa saling menghormati.<br>Melalui sosialisasi ini, Anna Mu’awanah berharap nilai-nilai Empat Pilar tidak hanya dipahami secara teoritis, tetapi benar-benar diimplementasikan dalam kehidupan sehari-hari. Ia juga mengajak seluruh elemen masyarakat Tuban untuk ikut menjadi agen penguatan karakter bangsa di lingkungannya masing-masing.<br>Kegiatan sosialisasi yang berlangsung hingga siang hari tersebut ditutup dengan sesi dialog interaktif antara peserta dan narasumber, yang membahas berbagai persoalan kebangsaan dan tantangan karakter bangsa di era digital.</p>\";s:12:\"published_at\";s:19:\"2025-12-09 12:11:02\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2025-12-10 05:11:23\";s:10:\"updated_at\";s:19:\"2025-12-10 14:29:58\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:7:{i:0;s:7:\"user_id\";i:1;s:5:\"title\";i:2;s:4:\"slug\";i:3;s:5:\"image\";i:4;s:4:\"body\";i:5;s:12:\"published_at\";i:6;s:8:\"featured\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:16:\"\0*\0forceDeleting\";b:0;}i:9;O:15:\"App\\Models\\Post\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"posts\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:11:{s:2:\"id\";i:2;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KC5XQKCEYQ6E6B5FDC559KJ6.jpeg\";s:5:\"title\";s:132:\"Anna Mu\'awanah : Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika sebagai landasan utama dalam kehidupan berbangsa dan bernegara.\";s:4:\"slug\";s:125:\"anna-muawanah-pancasila-uud-1945-nkri-dan-bhinneka-tunggal-ika-sebagai-landasan-utama-dalam-kehidupan-berbangsa-dan-bernegara\";s:4:\"body\";s:2831:\"<p>Tuban 9 Desember 2025 – Suasana pagi di Kabupaten Tuban terasa berbeda pada kegiatan Sosialisasi Empat Pilar Kebangsaan yang digelar oleh Anggota DPR RI, Anna Muawanah. Sejak pagi hari, ratusan peserta dari berbagai latar belakang masyarakat telah memadati lokasi kegiatan dengan semangat untuk memperdalam pemahaman tentang Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika sebagai landasan utama dalam kehidupan berbangsa dan bernegara.<br>Dalam pemaparannya, Anna Muawanah menegaskan bahwa tantangan kebangsaan saat ini semakin kompleks, terutama di tengah derasnya arus informasi dan perubahan sosial yang begitu cepat. Menurutnya, pemahaman terhadap Empat Pilar Kebangsaan tidak boleh hanya menjadi hafalan, tetapi harus diimplementasikan dalam sikap dan perilaku sehari-hari.<br>“Empat Pilar Kebangsaan adalah fondasi utama kita sebagai bangsa. Jika fondasi ini kuat, maka kita tidak mudah terpecah oleh isu-isu yang melemahkan persatuan, baik itu hoaks, intoleransi, maupun pengaruh negatif dari media sosial,” tegas Anna Muawanah di hadapan peserta.<br>Ia juga menyoroti pentingnya menanamkan nilai-nilai kebangsaan sejak dini, khususnya kepada generasi muda. Menurutnya, Pancasila mengajarkan nilai gotong royong dan keadilan sosial, UUD 1945 menjamin hak dan kewajiban warga negara, NKRI adalah bentuk harga diri bangsa, sementara Bhinneka Tunggal Ika menjadi perekat dalam keberagaman.<br>“Kita boleh berbeda suku, agama, dan pandangan, tetapi kita tetap satu sebagai bangsa Indonesia. Inilah esensi dari Bhinneka Tunggal Ika yang harus terus kita rawat,” tambahnya.<br>Kegiatan sosialisasi ini juga diisi dengan sesi dialog interaktif. Salah satu peserta, Suyanto, warga Kecamatan Singgahan, mengungkapkan bahwa kegiatan ini sangat bermanfaat untuk membuka kembali pemahaman masyarakat tentang pentingnya nilai-nilai kebangsaan di tengah kondisi sosial saat ini.<br>“Di era sekarang, banyak generasi muda yang mulai abai dengan nilai kebangsaan. Melalui kegiatan seperti ini, kami jadi lebih paham bahwa Empat Pilar bukan sekadar teori, tetapi pedoman hidup berbangsa,” ujarnya.<br>Sementara itu, peserta lainnya, Nur Aini, menilai bahwa sosialisasi Empat Pilar sangat relevan dengan kondisi masyarakat saat ini yang mudah terpengaruh informasi di media sosial.<br>“Kami jadi lebih sadar untuk menyaring informasi dan tidak mudah terprovokasi. Ini penting agar persatuan tetap terjaga,” tuturnya.<br>Melalui sosialisasi yang berlangsung sejak pagi hari tersebut, Anna Muawanah berharap masyarakat Tuban semakin memiliki kesadaran kolektif untuk menjaga persatuan, menghormati perbedaan, serta mengamalkan nilai-nilai Pancasila dalam kehidupan sehari-hari. Ia juga menegaskan komitmennya untuk terus turun ke daerah dalam rangka memperkuat wawasan kebangsaan masyarakat di daerah pemilihannya.</p>\";s:12:\"published_at\";s:19:\"2025-12-09 08:27:22\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2025-12-10 01:28:33\";s:10:\"updated_at\";s:19:\"2025-12-11 05:27:09\";}s:11:\"\0*\0original\";a:11:{s:2:\"id\";i:2;s:7:\"user_id\";i:2;s:5:\"image\";s:48:\"posts/thumbnails/01KC5XQKCEYQ6E6B5FDC559KJ6.jpeg\";s:5:\"title\";s:132:\"Anna Mu\'awanah : Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika sebagai landasan utama dalam kehidupan berbangsa dan bernegara.\";s:4:\"slug\";s:125:\"anna-muawanah-pancasila-uud-1945-nkri-dan-bhinneka-tunggal-ika-sebagai-landasan-utama-dalam-kehidupan-berbangsa-dan-bernegara\";s:4:\"body\";s:2831:\"<p>Tuban 9 Desember 2025 – Suasana pagi di Kabupaten Tuban terasa berbeda pada kegiatan Sosialisasi Empat Pilar Kebangsaan yang digelar oleh Anggota DPR RI, Anna Muawanah. Sejak pagi hari, ratusan peserta dari berbagai latar belakang masyarakat telah memadati lokasi kegiatan dengan semangat untuk memperdalam pemahaman tentang Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika sebagai landasan utama dalam kehidupan berbangsa dan bernegara.<br>Dalam pemaparannya, Anna Muawanah menegaskan bahwa tantangan kebangsaan saat ini semakin kompleks, terutama di tengah derasnya arus informasi dan perubahan sosial yang begitu cepat. Menurutnya, pemahaman terhadap Empat Pilar Kebangsaan tidak boleh hanya menjadi hafalan, tetapi harus diimplementasikan dalam sikap dan perilaku sehari-hari.<br>“Empat Pilar Kebangsaan adalah fondasi utama kita sebagai bangsa. Jika fondasi ini kuat, maka kita tidak mudah terpecah oleh isu-isu yang melemahkan persatuan, baik itu hoaks, intoleransi, maupun pengaruh negatif dari media sosial,” tegas Anna Muawanah di hadapan peserta.<br>Ia juga menyoroti pentingnya menanamkan nilai-nilai kebangsaan sejak dini, khususnya kepada generasi muda. Menurutnya, Pancasila mengajarkan nilai gotong royong dan keadilan sosial, UUD 1945 menjamin hak dan kewajiban warga negara, NKRI adalah bentuk harga diri bangsa, sementara Bhinneka Tunggal Ika menjadi perekat dalam keberagaman.<br>“Kita boleh berbeda suku, agama, dan pandangan, tetapi kita tetap satu sebagai bangsa Indonesia. Inilah esensi dari Bhinneka Tunggal Ika yang harus terus kita rawat,” tambahnya.<br>Kegiatan sosialisasi ini juga diisi dengan sesi dialog interaktif. Salah satu peserta, Suyanto, warga Kecamatan Singgahan, mengungkapkan bahwa kegiatan ini sangat bermanfaat untuk membuka kembali pemahaman masyarakat tentang pentingnya nilai-nilai kebangsaan di tengah kondisi sosial saat ini.<br>“Di era sekarang, banyak generasi muda yang mulai abai dengan nilai kebangsaan. Melalui kegiatan seperti ini, kami jadi lebih paham bahwa Empat Pilar bukan sekadar teori, tetapi pedoman hidup berbangsa,” ujarnya.<br>Sementara itu, peserta lainnya, Nur Aini, menilai bahwa sosialisasi Empat Pilar sangat relevan dengan kondisi masyarakat saat ini yang mudah terpengaruh informasi di media sosial.<br>“Kami jadi lebih sadar untuk menyaring informasi dan tidak mudah terprovokasi. Ini penting agar persatuan tetap terjaga,” tuturnya.<br>Melalui sosialisasi yang berlangsung sejak pagi hari tersebut, Anna Muawanah berharap masyarakat Tuban semakin memiliki kesadaran kolektif untuk menjaga persatuan, menghormati perbedaan, serta mengamalkan nilai-nilai Pancasila dalam kehidupan sehari-hari. Ia juga menegaskan komitmennya untuk terus turun ke daerah dalam rangka memperkuat wawasan kebangsaan masyarakat di daerah pemilihannya.</p>\";s:12:\"published_at\";s:19:\"2025-12-09 08:27:22\";s:8:\"featured\";i:1;s:10:\"deleted_at\";N;s:10:\"created_at\";s:19:\"2025-12-10 01:28:33\";s:10:\"updated_at\";s:19:\"2025-12-11 05:27:09\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:2:{s:12:\"published_at\";s:8:\"datetime\";s:10:\"deleted_at\";s:8:\"datetime\";